    var evidenceRoot = Path.Combine(Path.GetTempPath(), "Callsign.AlphaSmoke", "parity-evidence-summary", Guid.NewGuid().ToString("N"));
    try
    {
        Directory.CreateDirectory(evidenceRoot);
        var evidencePath = Path.Combine(evidenceRoot, "voice-access-parity-evidence.json");
        File.WriteAllText(evidencePath, """
        {
          "release_ready": false,
          "release_blocker_summary": {
            "blocker_count": 5,
            "manual_evidence_supplied": false,
            "manual_checks_remaining_count": 4,
            "manual_categories_missing_count": 4,
            "failed_automated_checks_count": 0,
            "next_action": "Complete manual evidence."
          },
          "manual_evidence": {
            "remaining": [
              "Clean install proof",
              "Human-spoken walkthrough",
              "Show numbers walkthrough",
              "Fourth proof should stay hidden"
            ],
            "categories_missing": [
              "App launch",
              "Voice access controls",
              "Voice shortcuts",
              "Fourth category should stay hidden"
            ]
          }
        }
        """);
        var evidenceSummary = (string?)paritySummaryMethod!.Invoke(null, [evidencePath]) ?? string.Empty;
        Require(evidenceSummary.Contains("release-ready false", StringComparison.OrdinalIgnoreCase), $"Expected evidence summary to include release-ready state, got '{evidenceSummary}'.");
        Require(evidenceSummary.Contains("manual evidence not supplied", StringComparison.OrdinalIgnoreCase), $"Expected evidence summary to name missing manual evidence, got '{evidenceSummary}'.");
        Require(evidenceSummary.Contains("remaining proof: Clean install proof | Human-spoken walkthrough | Show numbers walkthrough", StringComparison.OrdinalIgnoreCase), $"Expected evidence summary to preview first three remaining proof items, got '{evidenceSummary}'.");
        Require(!evidenceSummary.Contains("Fourth proof should stay hidden", StringComparison.OrdinalIgnoreCase), $"Expected evidence summary to bound remaining proof preview, got '{evidenceSummary}'.");
        Require(evidenceSummary.Contains("missing categories: App launch | Voice access controls | Voice shortcuts", StringComparison.OrdinalIgnoreCase), $"Expected evidence summary to preview first three missing categories, got '{evidenceSummary}'.");
        Require(!evidenceSummary.Contains("Fourth category should stay hidden", StringComparison.OrdinalIgnoreCase), $"Expected evidence summary to bound missing category preview, got '{evidenceSummary}'.");
