    var readEvidenceHeaderButtonProperty = typeof(MainForm).GetProperty("ReadEvidenceHeaderButtonText", BindingFlags.Instance | BindingFlags.Public);
    Require(readEvidenceHeaderButtonProperty != null, "MainForm should expose the evidence-header readback button text.");
    var readEvidenceHeaderButtonText = readEvidenceHeaderButtonProperty!.GetValue(form) as string ?? string.Empty;
    Require(readEvidenceHeaderButtonText.Contains("Read Evidence Header", StringComparison.OrdinalIgnoreCase), $"Expected read-evidence-header button text, got '{readEvidenceHeaderButtonText}'.");
    var createEvidenceDraftButtonProperty = typeof(MainForm).GetProperty("CreateEvidenceDraftButtonText", BindingFlags.Instance | BindingFlags.Public);
    Require(createEvidenceDraftButtonProperty != null, "MainForm should expose the evidence-draft button text.");
    var createEvidenceDraftButtonText = createEvidenceDraftButtonProperty!.GetValue(form) as string ?? string.Empty;
    Require(createEvidenceDraftButtonText.Contains("Create Evidence Draft", StringComparison.OrdinalIgnoreCase), $"Expected create-evidence-draft button text, got '{createEvidenceDraftButtonText}'.");
    var createAllProofNotesButtonProperty = typeof(MainForm).GetProperty("CreateAllProofNotesButtonText", BindingFlags.Instance | BindingFlags.Public);
    Require(createAllProofNotesButtonProperty != null, "MainForm should expose the all-proof-notes button text.");
    var createAllProofNotesButtonText = createAllProofNotesButtonProperty!.GetValue(form) as string ?? string.Empty;
    Require(createAllProofNotesButtonText.Contains("Create All Notes", StringComparison.OrdinalIgnoreCase), $"Expected create-all-proof-notes button text, got '{createAllProofNotesButtonText}'.");
    var allProofNotePaths = MainForm.CreateAllProofNoteFiles();
    Require(allProofNotePaths.Count > 0, "CreateAllProofNoteFiles should prepare at least one manual proof note.");
    Require(allProofNotePaths.All(File.Exists), "CreateAllProofNoteFiles should write each returned proof note path.");
    var firstProofNoteText = File.ReadAllText(allProofNotePaths[0]);
    Require(firstProofNoteText.Contains("## Evidence Command", StringComparison.OrdinalIgnoreCase), "Bulk proof notes should include an evidence command section.");
    Require(firstProofNoteText.Contains("## Privacy Review", StringComparison.OrdinalIgnoreCase), "Bulk proof notes should include a privacy review section.");
    var openEvidenceDraftButtonProperty = typeof(MainForm).GetProperty("OpenEvidenceDraftButtonText", BindingFlags.Instance | BindingFlags.Public);
    Require(openEvidenceDraftButtonProperty != null, "MainForm should expose the evidence-draft open button text.");
    var openEvidenceDraftButtonText = openEvidenceDraftButtonProperty!.GetValue(form) as string ?? string.Empty;
    Require(openEvidenceDraftButtonText.Contains("Open Evidence Draft", StringComparison.OrdinalIgnoreCase), $"Expected open-evidence-draft button text, got '{openEvidenceDraftButtonText}'.");
    var readEvidenceDraftButtonProperty = typeof(MainForm).GetProperty("ReadEvidenceDraftButtonText", BindingFlags.Instance | BindingFlags.Public);
    Require(readEvidenceDraftButtonProperty != null, "MainForm should expose the evidence-draft readback button text.");
    var readEvidenceDraftButtonText = readEvidenceDraftButtonProperty!.GetValue(form) as string ?? string.Empty;
    Require(readEvidenceDraftButtonText.Contains("Read Evidence Draft", StringComparison.OrdinalIgnoreCase), $"Expected read-evidence-draft button text, got '{readEvidenceDraftButtonText}'.");
    var evidenceDraftPath = MainForm.CreateManualEvidenceDraftFile();
    Require(!string.IsNullOrWhiteSpace(evidenceDraftPath) && File.Exists(evidenceDraftPath), "CreateManualEvidenceDraftFile should write a visible manual evidence draft.");
    using var evidenceDraftDocument = JsonDocument.Parse(File.ReadAllText(evidenceDraftPath!));
    var evidenceDraftRoot = evidenceDraftDocument.RootElement;
    Require(evidenceDraftRoot.TryGetProperty("evidence_header", out var evidenceHeader), "Manual evidence draft should include an evidence_header block.");
    Require(evidenceHeader.TryGetProperty("artifact_hashes", out var artifactHashes) && artifactHashes.ValueKind == JsonValueKind.Array && artifactHashes.GetArrayLength() > 0, "Manual evidence draft should prefill artifact hashes.");
    Require(evidenceHeader.TryGetProperty("tested_utc", out var testedUtc) && !string.IsNullOrWhiteSpace(testedUtc.GetString()), "Manual evidence draft should prefill tested_utc.");
    Require(evidenceDraftRoot.TryGetProperty("local_installer_sha256", out var localInstallerSha) && !string.IsNullOrWhiteSpace(localInstallerSha.GetString()), "Manual evidence draft should prefill the local installer SHA-256.");
}

