static void UpdateSplashShowsFeatureOnlyManifests()
{
    var stateRoot = Path.Combine(Path.GetTempPath(), "Callsign.AlphaSmoke.UpdateSplash", Guid.NewGuid().ToString("N"));
    Directory.CreateDirectory(stateRoot);

    using var form = new MainForm(stateRoot: stateRoot);
    var lastShownField = typeof(MainForm).GetField("_lastShownManifestVersion", BindingFlags.Instance | BindingFlags.NonPublic);
    Require(lastShownField != null, "MainForm should expose the last-shown manifest version field for splash reset.");
    lastShownField!.SetValue(form, null);
    var manifest = new CallsignUpdateManifest(
        Version: "9.9.9-feature-only",
        InstallerUrl: "https://updates.example.test/Callsign-Setup.exe",
        InstallerSha256: new string('c', 64),
        InstallerSizeBytes: 123,
        ReleaseNotes: "Feature-only manifest.",
        FeatureHighlights:
        [
            new CallsignUpdateFeatureChange(
                FeatureId: "dictation-review-surface",
                DisplayName: "Dictation review surface",
                Category: "Dictation",
                Summary: "Adds a visible review surface for dictated text.")
        ],
        PublishedUtc: DateTimeOffset.UtcNow);

    var shouldShowMethod = typeof(MainForm).GetMethod("ShouldShowSplashForManifest", BindingFlags.Instance | BindingFlags.NonPublic);
    var showUpdateMethod = typeof(MainForm).GetMethod("ShowUpdateSplash", BindingFlags.Instance | BindingFlags.NonPublic);
    var updateSplashField = typeof(MainForm).GetField("_updateSplash", BindingFlags.Instance | BindingFlags.NonPublic);

    Require(shouldShowMethod != null, "MainForm should expose a manifest visibility gate for feature-only update splashes.");
    Require(showUpdateMethod != null, "MainForm should expose a visible update splash launcher for feature-only manifests.");
    Require(updateSplashField != null, "MainForm should keep a reference to the active update splash.");

    var gate = (bool?)shouldShowMethod!.Invoke(form, new object[] { manifest });
    Require(gate == true, "Feature-only manifests should still show the update splash.");

    showUpdateMethod!.Invoke(form, new object[] { manifest });
    var splash = updateSplashField!.GetValue(form) as UpdateSplashForm;
    Require(splash != null, "Feature-only manifests should create an update splash.");
    Require(splash!.ScopeBadgeText.Contains("Scope:", StringComparison.OrdinalIgnoreCase), $"Expected update splash scope badge text, got '{splash.ScopeBadgeText}'.");
    Require(splash.KindBadgeText.Contains("feature-only", StringComparison.OrdinalIgnoreCase), $"Expected feature-only splash kind badge to say feature-only, got '{splash.KindBadgeText}'.");
    Require(splash.SummaryText.Contains("Feature-only update", StringComparison.OrdinalIgnoreCase), $"Expected feature-only splash summary to say feature-only update, got '{splash.SummaryText}'.");
    Require(splash!.HighlightText.Contains("Features:", StringComparison.OrdinalIgnoreCase), $"Expected feature-only splash highlights to name features, got '{splash.HighlightText}'.");
    Require(splash.DetailsText.Contains("[Features]", StringComparison.OrdinalIgnoreCase), $"Expected feature-only splash details to include the feature section, got '{splash.DetailsText}'.");
    Require(splash.DetailsText.Contains("dictation-review-surface", StringComparison.OrdinalIgnoreCase), $"Expected feature-only splash details to name the feature id, got '{splash.DetailsText}'.");
    Require(splash.CueText.Contains("features: 1", StringComparison.OrdinalIgnoreCase), $"Expected feature-only splash cue to count features, got '{splash.CueText}'.");

    splash.Hide();
}

