static void UpdateSplashStillShowsAfterManifestStateIsRecorded()
{
    using var form = new MainForm();
    var manifest = new CallsignUpdateManifest(
        "1.4.1a",
        "https://updates.example.test/Callsign-Setup.exe",
        "ABCDEFABCDEFABCDEFABCDEFABCDEFABCDEFABCDEFABCDEFABCDEFABCDEFABCD",
        123,
        "Visible controls update.",
        AddedCommands: new[]
        {
            new CallsignUpdateCommandChange("show-numbers", "Show numbers", "Visible controls", "Show numbered controls visibly.")
        },
        SplashSummary: "Visible controls update.",
        PublishedUtc: DateTimeOffset.UtcNow);

    var shouldShowMethod = typeof(MainForm).GetMethod("ShouldShowSplashForManifest", BindingFlags.Instance | BindingFlags.NonPublic);
    var showUpdateMethod = typeof(MainForm).GetMethod("ShowUpdateSplash", BindingFlags.Instance | BindingFlags.NonPublic);
    var updateSplashField = typeof(MainForm).GetField("_updateSplash", BindingFlags.Instance | BindingFlags.NonPublic);
    var lastShownField = typeof(MainForm).GetField("_lastShownManifestVersion", BindingFlags.Instance | BindingFlags.NonPublic);

    Require(shouldShowMethod != null, "MainForm should expose a manifest visibility gate for update splashes.");
    Require(showUpdateMethod != null, "MainForm should expose a visible update splash launcher.");
    Require(updateSplashField != null, "MainForm should keep a reference to the active update splash.");
    Require(lastShownField != null, "MainForm should persist the last shown update manifest version.");

    lastShownField!.SetValue(form, null);
    var firstGate = (bool?)shouldShowMethod!.Invoke(form, new object[] { manifest });
    Require(firstGate == true, "The first visibility check for a new manifest should allow the splash.");

    showUpdateMethod!.Invoke(form, new object[] { manifest });

    var splash = updateSplashField!.GetValue(form) as UpdateSplashForm;
    Require(splash != null, "Update splash should still be created after the manifest visibility gate has been evaluated.");
    var shownSplash = splash!;
    Require(shownSplash.TitleText.Contains("1.4.1a", StringComparison.OrdinalIgnoreCase), $"Expected splash title to reflect the new manifest, got '{shownSplash.TitleText}'.");
    Require(string.Equals(lastShownField!.GetValue(form)?.ToString(), "1.4.1a", StringComparison.OrdinalIgnoreCase), "MainForm should record the shown manifest version after displaying the update splash.");

    shownSplash.Hide();
}

static void UpdateCheckFailureDoesNotAdvanceDueWindow()
{
    Console.WriteLine("BEGIN update failure test");
    using var client = new HttpClient(new StaticResponseHandler(HttpStatusCode.InternalServerError, "{\"error\":\"not ready\"}"));
    var statePath = Path.Combine(Path.GetTempPath(), "Callsign.AlphaSmoke.Update", Guid.NewGuid().ToString("N"), "updates-state.json");
    var service = new UpdateCheckService(serverUrl: "http://localhost:5087", checkInterval: TimeSpan.FromHours(25), httpClient: client, statePath: statePath);
    SetField(service, "_installedExecutablePath", string.Empty);
    Require(service.IsCheckDue(DateTimeOffset.UtcNow), "Fresh update service should treat the check as due.");

    var result = service.CheckForUpdateAsync(force: true, attemptInstall: false).GetAwaiter().GetResult();

    Require(!result.Succeeded, $"Expected failed update check against a local error response, got success message '{result.Message}'.");
    Require(service.IsCheckDue(DateTimeOffset.UtcNow), "A failed update check should not postpone the next due window.");
    Console.WriteLine("END update failure test");
}

static void UpdateCheckSuccessAdvancesDueWindow()
{
    Console.WriteLine("BEGIN update success test");
    var manifestJson = """
    {
      "version": "9.9.9a",
      "installerUrl": "",
      "installerSha256": "",
      "installerSizeBytes": 0,
      "notes": "Voice Access parity hardening.",
      "title": "Voice Access parity hardening.",
      "artifactUrl": "",
      "sizeBytes": 0,
      "publishedUtc": "2026-06-24T12:00:00+00:00"
    }
    """;

    using var client = new HttpClient(new StaticResponseHandler(HttpStatusCode.OK, manifestJson));
    var statePath = Path.Combine(Path.GetTempPath(), "Callsign.AlphaSmoke.Update", Guid.NewGuid().ToString("N"), "updates-state.json");
    var service = new UpdateCheckService(serverUrl: "http://localhost:5087", checkInterval: TimeSpan.FromHours(25), httpClient: client, statePath: statePath);
    SetField(service, "_installedExecutablePath", string.Empty);
    Require(service.IsCheckDue(DateTimeOffset.UtcNow), "Fresh update service should treat the check as due.");

    var result = service.CheckForUpdateAsync(force: true, attemptInstall: false).GetAwaiter().GetResult();

    Require(result.Succeeded, $"Expected update check to succeed against the local manifest server, got '{result.Message}'.");
    Require(result.UpdateAvailable, "Expected the local manifest to be treated as an available update.");
    Require(result.Manifest != null, "Expected the local manifest to be captured in the result.");
    Require(string.Equals(result.Manifest!.Version, "9.9.9a", StringComparison.OrdinalIgnoreCase), $"Expected the manifest version to round-trip, got '{result.Manifest.Version}'.");
    Require(!service.IsCheckDue(DateTimeOffset.UtcNow), "A successful update check should advance the due window.");
    Console.WriteLine("END update success test");
}

static void UpdateCheckIgnoresInstallerHashWhenVersionMatches()
{
    Console.WriteLine("BEGIN update hash/version parity test");
    var localVersion = GetCurrentExecutableVersion();
    var manifestJson = $$"""
    {
      "version": "{{localVersion}}",
      "installerUrl": "",
      "installerSha256": "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA",
      "installerSizeBytes": 1234,
      "notes": "Version match should not depend on installer hash.",
      "title": "Version match should not depend on installer hash.",
      "artifactUrl": "",
      "sizeBytes": 1234,
      "publishedUtc": "2026-06-24T12:00:00+00:00"
    }
    """;

    using var client = new HttpClient(new StaticResponseHandler(HttpStatusCode.OK, manifestJson));
    var statePath = Path.Combine(Path.GetTempPath(), "Callsign.AlphaSmoke.Update", Guid.NewGuid().ToString("N"), "updates-state.json");
    var service = new UpdateCheckService(serverUrl: "http://localhost:5087", checkInterval: TimeSpan.FromHours(25), httpClient: client, statePath: statePath);
    SetField(service, "_installedExecutablePath", string.Empty);

    var result = service.CheckForUpdateAsync(force: true, attemptInstall: false).GetAwaiter().GetResult();

    Require(result.Succeeded, $"Expected update check to succeed when the version matches, got '{result.Message}'.");
    Require(!result.UpdateAvailable, "Expected a matching version to be treated as up to date even when the installer hash differs.");
    Require(result.Message.Contains("up to date", StringComparison.OrdinalIgnoreCase), $"Expected the result message to report that Callsign is up to date, got '{result.Message}'.");
    Console.WriteLine("END update hash/version parity test");
}

static void UpdateCheckStateSurvivesRestart()
{
    Console.WriteLine("BEGIN update restart persistence test");
    var manifestJson = """
    {
      "version": "9.9.10a",
      "installerUrl": "",
      "installerSha256": "",
      "installerSizeBytes": 0,
      "notes": "Restart persistence proof.",
      "title": "Restart persistence proof.",
      "artifactUrl": "",
      "sizeBytes": 0,
      "publishedUtc": "2026-06-24T12:00:00+00:00"
    }
    """;

    var statePath = Path.Combine(Path.GetTempPath(), "Callsign.AlphaSmoke.Update", Guid.NewGuid().ToString("N"), "updates-state.json");

    try
    {
        using (var client = new HttpClient(new StaticResponseHandler(HttpStatusCode.OK, manifestJson)))
        {
            var service = new UpdateCheckService(serverUrl: "http://localhost:5087", checkInterval: TimeSpan.FromHours(25), httpClient: client, statePath: statePath);
            SetField(service, "_installedExecutablePath", string.Empty);

            var result = service.CheckForUpdateAsync(force: true, attemptInstall: false).GetAwaiter().GetResult();

            Require(result.Succeeded, $"Expected update check to succeed before restart persistence verification, got '{result.Message}'.");
            Require(result.UpdateAvailable, "Expected the update manifest to be available before restart persistence verification.");
            Require(result.Manifest != null, "Expected the update manifest to be captured before restart persistence verification.");
        }

        using var reloadedClient = new HttpClient(new StaticResponseHandler(HttpStatusCode.OK, "{}"));
        var reloadedService = new UpdateCheckService(serverUrl: "http://localhost:5087", checkInterval: TimeSpan.FromHours(25), httpClient: reloadedClient, statePath: statePath);

        Require(reloadedService.LastKnownVersion == "9.9.10a", $"Expected last known version to survive restart, got '{reloadedService.LastKnownVersion}'.");
        Require(reloadedService.PendingManifest != null, "Expected pending manifest data to survive restart.");
        Require(string.Equals(reloadedService.PendingManifest!.Version, "9.9.10a", StringComparison.OrdinalIgnoreCase), $"Expected reloaded pending manifest version to survive restart, got '{reloadedService.PendingManifest.Version}'.");
        Require(!reloadedService.IsCheckDue(DateTimeOffset.UtcNow), "Expected the saved update check to keep the due window closed after restart.");

        var status = reloadedService.DescribeStatus(DateTimeOffset.UtcNow);
        Require(status.Contains("9.9.10a", StringComparison.OrdinalIgnoreCase), $"Expected reloaded status to include the manifest version, got '{status}'.");
        Require(status.Contains("next due", StringComparison.OrdinalIgnoreCase), $"Expected reloaded status to include next-due timing, got '{status}'.");
        Console.WriteLine("END update restart persistence test");
    }
    finally
    {
        if (File.Exists(statePath))
            File.Delete(statePath);
    }
}

static void UpdateCheckDownloadedInstallerPathSurvivesRestart()
{
    var statePath = Path.Combine(Path.GetTempPath(), "Callsign.AlphaSmoke.Update", Guid.NewGuid().ToString("N"), "updates-state.json");
    var downloadedInstallerPath = Path.Combine(Path.GetTempPath(), "Callsign.AlphaSmoke.Update", Guid.NewGuid().ToString("N"), "Callsign-Setup.exe");

    try
    {
        Directory.CreateDirectory(Path.GetDirectoryName(downloadedInstallerPath)!);
        File.WriteAllText(downloadedInstallerPath, "installer");

        var stateJson = $$"""
        {
          "lastCheckUtc": "2026-06-24T12:00:00+00:00",
          "lastKnownVersion": "9.9.11a",
          "lastUpdateAttemptedUtc": "2026-06-24T12:15:00+00:00",
          "lastDownloadedInstallerPath": "{{downloadedInstallerPath.Replace("\\", "\\\\")}}",
