static void UpdateServiceSendsCheckInPayloadWhenPhoningHome()
{
    var handler = new RecordingResponseHandler(HttpStatusCode.OK, "{}");
    using var client = new HttpClient(handler);
    var statePath = Path.Combine(Path.GetTempPath(), $"callsign-update-state-{Guid.NewGuid():N}.json");

    try
    {
        var service = new UpdateCheckService("alpha", "https://updates.example.test", TimeSpan.FromHours(25), client, statePath);
        var snapshot = service.BuildCheckInPayloadSnapshot("Alpha Callsign", "1.2.3", "device-1", DateTimeOffset.Parse("2026-06-24T12:00:00+00:00", CultureInfo.InvariantCulture));

        Require(snapshot.AccountId != null && snapshot.AccountId.StartsWith("sha256:", StringComparison.OrdinalIgnoreCase), $"Expected snapshot account id to be hashed, got '{snapshot.AccountId}'.");
        Require(snapshot.DeviceId != null && snapshot.DeviceId.StartsWith("sha256:", StringComparison.OrdinalIgnoreCase), $"Expected snapshot device id to be hashed, got '{snapshot.DeviceId}'.");
        Require(!string.Equals(snapshot.AccountId, "Alpha Callsign", StringComparison.OrdinalIgnoreCase), "Check-in snapshot must not preserve the raw account/callsign value.");
        Require(!string.Equals(snapshot.DeviceId, "device-1", StringComparison.OrdinalIgnoreCase), "Check-in snapshot must not preserve the raw local device id.");
        Require(string.Equals(snapshot.AccountId, UpdateCheckService.BuildPrivacyPreservingIdentifier("account", "Alpha Callsign"), StringComparison.OrdinalIgnoreCase), "Check-in snapshot should use the shared privacy-preserving account identifier builder.");
        Require(string.Equals(snapshot.DeviceId, UpdateCheckService.BuildPrivacyPreservingIdentifier("device", "device-1"), StringComparison.OrdinalIgnoreCase), "Check-in snapshot should use the shared privacy-preserving device identifier builder.");
        Require(snapshot.InstalledAtUtc == snapshot.RequestedAtUtc, "Check-in snapshot should use one bounded timestamp for installed/requested proof.");
        var snapshotJson = JsonSerializer.Serialize(snapshot);
        Require(!snapshotJson.Contains("Alpha Callsign", StringComparison.OrdinalIgnoreCase), $"Expected serialized check-in snapshot to avoid the raw callsign, got '{snapshotJson}'.");
        Require(!snapshotJson.Contains("device-1", StringComparison.OrdinalIgnoreCase), $"Expected serialized check-in snapshot to avoid the raw device id, got '{snapshotJson}'.");

        service.SendCheckInAsync("Alpha", "1.2.3", "device-1").GetAwaiter().GetResult();

        Require(handler.RequestCount == 1, $"Expected a single check-in POST, got {handler.RequestCount}.");
        Require(handler.LastRequest != null, "Expected the phone-home request to be recorded.");
        Require(handler.LastRequest!.Method == HttpMethod.Post, $"Expected check-in to POST, got {handler.LastRequest.Method}.");
        Require(handler.LastRequest.RequestUri != null && string.Equals(handler.LastRequest.RequestUri.AbsolutePath, "/api/checkins", StringComparison.OrdinalIgnoreCase), $"Expected check-in to target /api/checkins, got '{handler.LastRequest.RequestUri}'.");
        Require(!handler.LastRequestBody.Contains("\"accountId\":\"Alpha\"", StringComparison.OrdinalIgnoreCase), $"Expected check-in payload to avoid the raw account id, got '{handler.LastRequestBody}'.");
        Require(handler.LastRequestBody.Contains("\"accountId\":\"sha256:", StringComparison.OrdinalIgnoreCase), $"Expected check-in payload to include a hashed account id, got '{handler.LastRequestBody}'.");
        Require(handler.LastRequestBody.Contains("\"channel\":\"alpha\"", StringComparison.OrdinalIgnoreCase), $"Expected check-in payload to include the channel, got '{handler.LastRequestBody}'.");
        Require(handler.LastRequestBody.Contains("\"appVersion\":\"1.2.3\"", StringComparison.OrdinalIgnoreCase), $"Expected check-in payload to include the app version, got '{handler.LastRequestBody}'.");
        Require(!handler.LastRequestBody.Contains("device-1", StringComparison.OrdinalIgnoreCase), $"Expected check-in payload to avoid the raw device id, got '{handler.LastRequestBody}'.");
        Require(handler.LastRequestBody.Contains("\"deviceId\":\"sha256:", StringComparison.OrdinalIgnoreCase), $"Expected check-in payload to include a hashed device id, got '{handler.LastRequestBody}'.");
        Require(handler.LastRequestBody.Contains("\"installedVersion\":\"1.2.3\"", StringComparison.OrdinalIgnoreCase), $"Expected check-in payload to include the installed version, got '{handler.LastRequestBody}'.");
        Require(service.LastCheckInUtc.HasValue, "Expected a successful phone-home request to update the last check-in timestamp.");
    }
    finally
    {
        if (File.Exists(statePath))
            File.Delete(statePath);
    }
}

