    walkthrough.OpenReleaseProofStep();

    Require(walkthrough.CurrentStepText.Contains("Release Proof", StringComparison.OrdinalIgnoreCase), $"Expected the walkthrough to move to the release-proof step, got '{walkthrough.CurrentStepText}'.");
    Require(walkthrough.StatusLabelText.Contains("Step 17 of 17", StringComparison.OrdinalIgnoreCase), $"Expected the walkthrough status label to show the release-proof step number, got '{walkthrough.StatusLabelText}'.");
    Require(walkthrough.StatusLabelText.Contains("Release Proof", StringComparison.OrdinalIgnoreCase), $"Expected the walkthrough status label to name the release-proof surface, got '{walkthrough.StatusLabelText}'.");
    Require(walkthrough.StatusLabelText.Contains("release evidence folder", StringComparison.OrdinalIgnoreCase), $"Expected the walkthrough status label to mention the release evidence folder, got '{walkthrough.StatusLabelText}'.");
    Require(walkthrough.StatusLabelText.Contains("Open the release evidence folder", StringComparison.OrdinalIgnoreCase), $"Expected the walkthrough status label to include the release evidence folder reminder, got '{walkthrough.StatusLabelText}'.");
    Require(walkthrough.StatusLabelText.Contains("/downloads/Callsign-Setup.exe", StringComparison.OrdinalIgnoreCase), $"Expected the walkthrough status label to include the public download reminder, got '{walkthrough.StatusLabelText}'.");
    Require(walkthrough.StatusNextBadgeText.Contains("SHA-256", StringComparison.OrdinalIgnoreCase), $"Expected the walkthrough next badge to spell out the SHA-256 comparison, got '{walkthrough.StatusNextBadgeText}'.");
    Require(walkthrough.StatusProgressBadgeText.Contains("SHA-256", StringComparison.OrdinalIgnoreCase), $"Expected the walkthrough progress badge to spell out the SHA-256 comparison, got '{walkthrough.StatusProgressBadgeText}'.");
    Require(walkthrough.StatusBrowserBadgeText.Contains("Browser:", StringComparison.OrdinalIgnoreCase), $"Expected the browser helper badge to remain visible on the release-proof step, got '{walkthrough.StatusBrowserBadgeText}'.");
    Require(walkthrough.StatusReleaseBadgeText.Contains("compare installer + site", StringComparison.OrdinalIgnoreCase), $"Expected the release badge to remain visible on the release-proof step, got '{walkthrough.StatusReleaseBadgeText}'.");
    Require(walkthrough.StatusReleaseBadgeAccessibleDescription.Contains("SHA-256", StringComparison.OrdinalIgnoreCase) || walkthrough.StatusReleaseBadgeAccessibleDescription.Contains("No local Callsign-Setup.exe installer was found", StringComparison.OrdinalIgnoreCase), $"Expected the release badge to carry installer evidence, got '{walkthrough.StatusReleaseBadgeAccessibleDescription}'.");
    Require(walkthrough.StatusCurrentBadgeText.Contains("Release Proof", StringComparison.OrdinalIgnoreCase), $"Expected the current badge to reflect the release-proof surface, got '{walkthrough.StatusCurrentBadgeText}'.");
