static void StartupWalkthroughReleaseProofRouteOpensTheReleaseProofStep()
{
    using var form = new MainForm();
    var factoryMethod = typeof(MainForm).GetMethod("CreateStartupWalkthrough", BindingFlags.Instance | BindingFlags.NonPublic);
    Require(factoryMethod != null, "MainForm should expose a startup-walkthrough factory for the release-proof route.");

    using var walkthrough = factoryMethod!.Invoke(form, new object[] { true }) as StartupWalkthroughForm;
    Require(walkthrough != null, "MainForm should create a startup walkthrough for the release-proof route.");
    var mainFormSource = File.ReadAllText(Path.Combine(FindRepositoryRoot(), "src", "Callsign.UI", "MainForm.cs"));
    Require(mainFormSource.Contains("() => BuildReleaseProofText(_updateCheckService.PendingManifest)", StringComparison.OrdinalIgnoreCase), "MainForm should pass the current release-proof text into the startup walkthrough as a live provider.");
    Require(walkthrough!.CurrentStepText.Contains("Release Proof", StringComparison.OrdinalIgnoreCase), $"Expected the release-proof route to open the walkthrough at the release-proof step, got '{walkthrough.CurrentStepText}'.");
    Require(walkthrough.StatusLabelText.Contains("Step 17 of 17", StringComparison.OrdinalIgnoreCase), $"Expected the release-proof route to expose the release-proof step badge, got '{walkthrough.StatusLabelText}'.");
    Require(walkthrough.StatusLabelText.Contains("release evidence folder", StringComparison.OrdinalIgnoreCase), $"Expected the release-proof route to mention the release evidence folder, got '{walkthrough.StatusLabelText}'.");
    Require(walkthrough.StatusLabelText.Contains("SHA-256", StringComparison.OrdinalIgnoreCase) || walkthrough.StatusLabelText.Contains("No local Callsign-Setup.exe installer was found", StringComparison.OrdinalIgnoreCase), $"Expected the release-proof route to surface installer hash evidence in the visible status line, got '{walkthrough.StatusLabelText}'.");
    Require(
        walkthrough.ReleaseProofSummaryText.Contains("SHA-256", StringComparison.OrdinalIgnoreCase)
        || walkthrough.ReleaseProofSummaryText.Contains("No local Callsign-Setup.exe installer was found", StringComparison.OrdinalIgnoreCase)
        || walkthrough.ReleaseProofSummaryText.Contains("manifest has no staged installer URL yet", StringComparison.OrdinalIgnoreCase)
        || walkthrough.ReleaseProofSummaryText.Contains("release evidence folder", StringComparison.OrdinalIgnoreCase),
        $"Expected the release-proof route to surface installer, folder, or manifest evidence in the release summary line, got '{walkthrough.ReleaseProofSummaryText}'.");
    Require(
        walkthrough.VoiceCueText.Contains("open release proof", StringComparison.OrdinalIgnoreCase)
        || walkthrough.VoiceCueText.Contains("open release evidence", StringComparison.OrdinalIgnoreCase)
        || walkthrough.VoiceCueText.Contains("open updates", StringComparison.OrdinalIgnoreCase),
        $"Expected the release-proof route to expose a release-specific voice cue, got '{walkthrough.VoiceCueText}'.");
    Require(walkthrough.VoiceCueText.Contains("open release evidence", StringComparison.OrdinalIgnoreCase), $"Expected the update voice cue to mention release evidence, got '{walkthrough.VoiceCueText}'.");
    Require(walkthrough.VoiceCueText.Contains("read release proof", StringComparison.OrdinalIgnoreCase), $"Expected the release-proof voice cue to mention the readback route, got '{walkthrough.VoiceCueText}'.");
    Require(walkthrough.StatusCurrentBadgeText.Contains("Release Proof", StringComparison.OrdinalIgnoreCase), $"Expected the release-proof route to expose the release-proof current badge, got '{walkthrough.StatusCurrentBadgeText}'.");
    Require(walkthrough.StatusNextBadgeText.Contains("SHA-256", StringComparison.OrdinalIgnoreCase), $"Expected the release-proof route to spell out the SHA-256 comparison, got '{walkthrough.StatusNextBadgeText}'.");
    Require(walkthrough.StatusReleaseBadgeText.Contains("compare installer + site", StringComparison.OrdinalIgnoreCase), $"Expected the release-proof route to preserve the installer/site reminder, got '{walkthrough.StatusReleaseBadgeText}'.");
    Require(walkthrough.StatusReleaseBadgeAccessibleDescription.Contains("SHA-256", StringComparison.OrdinalIgnoreCase) || walkthrough.StatusReleaseBadgeAccessibleDescription.Contains("No local Callsign-Setup.exe installer was found", StringComparison.OrdinalIgnoreCase), $"Expected the release-proof route to expose installer evidence, got '{walkthrough.StatusReleaseBadgeAccessibleDescription}'.");
}

