static void StartupWalkthroughPacksButtonsInvokeTheImportAndFolderCallbacks()
{
    var lastTab = string.Empty;
    var importPackCount = 0;
    var importPackFolderCount = 0;
    var repeatImportSummaryCount = 0;
    var openPacksFolderCount = 0;

    using var walkthrough = new StartupWalkthroughForm(
        tabName => lastTab = tabName ?? string.Empty,
        _ => { },
        openReleaseEvidence: () => { },
        importPack: () => importPackCount++,
        importPackFolder: () => importPackFolderCount++,
        repeatImportSummary: () => repeatImportSummaryCount++,
        openPacksFolder: () => openPacksFolderCount++);

    var packsButtonField = typeof(StartupWalkthroughForm).GetField("_packsButton", BindingFlags.Instance | BindingFlags.NonPublic);
    var importPackButtonField = typeof(StartupWalkthroughForm).GetField("_importPackButton", BindingFlags.Instance | BindingFlags.NonPublic);
    var importPackFolderButtonField = typeof(StartupWalkthroughForm).GetField("_importPackFolderButton", BindingFlags.Instance | BindingFlags.NonPublic);
    var readImportSummaryButtonField = typeof(StartupWalkthroughForm).GetField("_readImportSummaryButton", BindingFlags.Instance | BindingFlags.NonPublic);
    var openPacksFolderButtonField = typeof(StartupWalkthroughForm).GetField("_openPacksFolderButton", BindingFlags.Instance | BindingFlags.NonPublic);

    Require(packsButtonField != null, "Startup walkthrough should expose the Packs jump button for review.");
    Require(importPackButtonField != null, "Startup walkthrough should expose the Import Pack button for review.");
    Require(importPackFolderButtonField != null, "Startup walkthrough should expose the Import Folder button for review.");
    var dropPackFolderButtonField = typeof(StartupWalkthroughForm).GetField("_dropPackFolderButton", BindingFlags.Instance | BindingFlags.NonPublic);
    Require(dropPackFolderButtonField != null, "Startup walkthrough should expose the Drop DLL Folder button for review.");
    Require(readImportSummaryButtonField != null, "Startup walkthrough should expose the Read Import Again button for review.");
    Require(openPacksFolderButtonField != null, "Startup walkthrough should expose the Open Packs Folder button for review.");

    var packsButton = packsButtonField!.GetValue(walkthrough) as Button;
    var importPackButton = importPackButtonField!.GetValue(walkthrough) as Button;
    var importPackFolderButton = importPackFolderButtonField!.GetValue(walkthrough) as Button;
    var dropPackFolderButton = dropPackFolderButtonField!.GetValue(walkthrough) as Button;
    var readImportSummaryButton = readImportSummaryButtonField!.GetValue(walkthrough) as Button;
    var openPacksFolderButton = openPacksFolderButtonField!.GetValue(walkthrough) as Button;

    Require(packsButton != null, "Startup walkthrough should build a visible Packs jump button.");
    Require(importPackButton != null, "Startup walkthrough should build a visible Import Pack button.");
    Require(importPackFolderButton != null, "Startup walkthrough should build a visible Import Folder button.");
    Require(dropPackFolderButton != null, "Startup walkthrough should build a visible Drop DLL Folder button.");
    Require(readImportSummaryButton != null, "Startup walkthrough should build a visible Read Import Again button.");
    Require(openPacksFolderButton != null, "Startup walkthrough should build a visible Open Packs Folder button.");

    RaiseButtonClick(packsButton!);
    Require(string.Equals(lastTab, "Packs", StringComparison.OrdinalIgnoreCase), $"Expected the walkthrough Packs button to navigate to the Packs surface, got '{lastTab}'.");
    Require(walkthrough.CurrentStepText.Contains("Packs", StringComparison.OrdinalIgnoreCase), $"Expected the walkthrough to move to the Packs step after pressing Packs, got '{walkthrough.CurrentStepText}'.");

    RaiseButtonClick(importPackButton!);
    RaiseButtonClick(importPackFolderButton!);
    RaiseButtonClick(readImportSummaryButton!);
    RaiseButtonClick(openPacksFolderButton!);

    Require(importPackCount == 1, $"Expected Import Pack to invoke its callback once, got {importPackCount}.");
    Require(importPackFolderCount == 1, $"Expected Import Folder to invoke its callback once, got {importPackFolderCount}.");
    Require(repeatImportSummaryCount == 1, $"Expected Read Import Again to invoke its callback once, got {repeatImportSummaryCount}.");
    Require(openPacksFolderCount == 1, $"Expected Open Packs Folder to invoke its callback once, got {openPacksFolderCount}.");
    Require(walkthrough.CurrentStepText.Contains("Packs", StringComparison.OrdinalIgnoreCase), $"Expected the walkthrough to remain on the Packs surface after importing or opening the folder, got '{walkthrough.CurrentStepText}'.");
}

static void RaiseButtonClick(Button button)
{
    var method = button.GetType().GetMethod("OnClick", BindingFlags.Instance | BindingFlags.NonPublic);
    Require(method != null, $"Could not raise click on button '{button.Text}'.");
    method!.Invoke(button, new object?[] { EventArgs.Empty });
}

static void StartupWalkthroughSeenStatePersistsAndSuppressesRepeats()
{
    var stateRoot = Path.Combine(Path.GetTempPath(), "Callsign.AlphaSmoke", Guid.NewGuid().ToString("N"));
    Directory.CreateDirectory(stateRoot);
    var statePath = Path.Combine(stateRoot, "startup-walkthrough-state.json");

    try
    {
        using var form = new MainForm();
        SetField(form, "_startupWalkthroughStatePath", statePath);

        var seenMethod = typeof(MainForm).GetMethod("HasSeenStartupWalkthrough", BindingFlags.Instance | BindingFlags.NonPublic);
        var persistMethod = typeof(MainForm).GetMethod("PersistStartupWalkthroughSeen", BindingFlags.Instance | BindingFlags.NonPublic);
        Require(seenMethod != null, "MainForm should expose startup-walkthrough seen-state inspection.");
        Require(persistMethod != null, "MainForm should expose startup-walkthrough seen-state persistence.");

        var initialSeen = (bool)seenMethod!.Invoke(form, null)!;
        Require(!initialSeen, "Fresh startup-walkthrough state should start unseen.");

        persistMethod!.Invoke(form, null);
        Require(File.Exists(statePath), "Persisting startup walkthrough state should create the state file.");

        using var persistedDocument = JsonDocument.Parse(File.ReadAllText(statePath));
        Require(
            persistedDocument.RootElement.TryGetProperty("HasSeenWalkthrough", out var hasSeenProperty) &&
            hasSeenProperty.ValueKind == JsonValueKind.True,
            $"Expected startup walkthrough state to persist a seen flag, got '{persistedDocument.RootElement}'.");

        var reloadedSeen = (bool)seenMethod.Invoke(form, null)!;
        Require(reloadedSeen, "Persisted startup walkthrough state should suppress repeats.");
    }
    finally
    {
        try
        {
            if (Directory.Exists(stateRoot))
                Directory.Delete(stateRoot, recursive: true);
        }
        catch
        {
        }
    }
}

static void StartupWalkthroughIsReachableFromAccountTab()
{
    using var form = new MainForm();
    var tabsField = typeof(MainForm).GetField("_tabs", BindingFlags.Instance | BindingFlags.NonPublic);
    Require(tabsField != null, "MainForm should expose the tab control field for walkthrough discovery.");
    var tabs = tabsField!.GetValue(form) as TabControl;
    Require(tabs != null, "MainForm should build the tab control during construction.");

    var accountTab = tabs!.TabPages.Cast<TabPage>().FirstOrDefault(page => string.Equals(page.Text, "Account", StringComparison.OrdinalIgnoreCase));
    Require(accountTab != null, "MainForm should include the Account tab.");

    var gettingStartedButton = EnumerateControls(accountTab!)
        .OfType<Button>()
        .FirstOrDefault(control => string.Equals(control.Text, "Getting Started", StringComparison.OrdinalIgnoreCase));

    if (gettingStartedButton is not Button button)
    {
        var allButtons = EnumerateControls(accountTab!)
            .OfType<Button>()
            .Select(control => control.Text)
            .ToArray();
        Require(false, $"Expected a Getting Started button on the Account tab, but found: {string.Join(", ", allButtons)}");
        return;
    }

    Require(button.Enabled, "Getting Started button should be enabled on the Account tab.");

    var accountButtons = EnumerateControls(accountTab!)
        .OfType<Button>()
        .Select(control => control.Text)
        .ToArray();
    Require(accountButtons.Contains("Voice Help", StringComparer.OrdinalIgnoreCase), $"Expected a Voice Help button on the Account tab, but found: {string.Join(", ", accountButtons)}");
    Require(accountButtons.Contains("Visible Controls", StringComparer.OrdinalIgnoreCase), $"Expected a Visible Controls button on the Account tab, but found: {string.Join(", ", accountButtons)}");
    Require(accountButtons.Contains("Show Numbers", StringComparer.OrdinalIgnoreCase), $"Expected a Show Numbers button on the Account tab, but found: {string.Join(", ", accountButtons)}");
