static void HelpTabExposesVisibleCommandDiscovery()
{
    using var form = new MainForm();
    var tabsField = typeof(MainForm).GetField("_tabs", BindingFlags.Instance | BindingFlags.NonPublic);
    Require(tabsField != null, "MainForm should expose the tab control field for help discovery.");
    var tabs = tabsField!.GetValue(form) as TabControl;
    Require(tabs != null, "MainForm should build the tab control during construction.");

    var helpTab = tabs!.TabPages.Cast<TabPage>().FirstOrDefault(page => string.Equals(page.Text, "Help", StringComparison.OrdinalIgnoreCase));
    Require(helpTab != null, "MainForm should include a Help tab.");

    var buttons = EnumerateControls(helpTab!)
        .OfType<Button>()
        .Select(control => control.Text)
        .ToArray();
    var searchBox = EnumerateControls(helpTab!)
        .OfType<TextBox>()
        .FirstOrDefault(control => string.Equals(control.AccessibleName, "Help search", StringComparison.OrdinalIgnoreCase));
    var commandsList = EnumerateControls(helpTab!)
        .OfType<ListBox>()
        .FirstOrDefault(control => string.Equals(control.AccessibleName, "Help command list", StringComparison.OrdinalIgnoreCase));
    Require(searchBox != null, "Expected a searchable Help tab input.");
    Require(commandsList != null, "Expected a visible Help command list.");
    Require(buttons.Contains("Open Palette", StringComparer.OrdinalIgnoreCase), $"Expected a command-palette button on the Help tab, but found: {string.Join(", ", buttons)}");
    Require(buttons.Contains("All Commands", StringComparer.OrdinalIgnoreCase), $"Expected an all-commands button on the Help tab, but found: {string.Join(", ", buttons)}");
