static void VoiceContractStripExposesEnrollmentFlow()
{
    using var form = new MainForm();
    var voiceContractProperty = typeof(MainForm).GetProperty("VoiceContractText", BindingFlags.Instance | BindingFlags.Public);
    Require(voiceContractProperty != null, "MainForm should expose the voice contract text.");
    var voiceContractText = voiceContractProperty!.GetValue(form) as string ?? string.Empty;
    Require(voiceContractText.Contains("record sample -> review voice state -> activate account", StringComparison.OrdinalIgnoreCase), $"Expected voice contract guidance, got '{voiceContractText}'.");
    var formSource = File.ReadAllText(Path.Combine(FindRepositoryRoot(), "src", "Callsign.UI", "MainForm.cs"));
    Require(formSource.Contains("AccessibleName = \"Voice status strip\"", StringComparison.OrdinalIgnoreCase), "Voice status strip should expose an accessible name.");
    Require(formSource.Contains("CreateVoiceBadge(\"Voice: ready to enroll\"", StringComparison.OrdinalIgnoreCase), "Voice status strip should expose a helpful voice-state badge.");
    Require(formSource.Contains("CreateVoiceBadge(\"Samples: 0 / 3\"", StringComparison.OrdinalIgnoreCase), "Voice status strip should expose a sample-count badge.");
    Require(formSource.Contains("CreateVoiceBadge(\"Playback: none\"", StringComparison.OrdinalIgnoreCase), "Voice status strip should expose a playback badge.");
    Require(formSource.Contains("CreateVoiceBadge(\"Next: create or pick profile\"", StringComparison.OrdinalIgnoreCase), "Voice status strip should expose a helpful next-step badge.");
    Require(formSource.Contains("RefreshVoicePanel()", StringComparison.OrdinalIgnoreCase), "Voice refresh should keep the status strip live.");
}

static void PacksContractStripExposesExtensionFlow()
{
    using var form = new MainForm();
    var packsContractProperty = typeof(MainForm).GetProperty("PacksContractText", BindingFlags.Instance | BindingFlags.Public);
    Require(packsContractProperty != null, "MainForm should expose the packs contract text.");
    var packsContractText = packsContractProperty!.GetValue(form) as string ?? string.Empty;
    Require(packsContractText.Contains("import locally -> review disabled -> enable by policy -> rollback or remove", StringComparison.OrdinalIgnoreCase), $"Expected packs contract guidance, got '{packsContractText}'.");

    var packsVoiceCueProperty = typeof(MainForm).GetProperty("PacksVoiceCueText", BindingFlags.Instance | BindingFlags.Public);
    Require(packsVoiceCueProperty != null, "MainForm should expose the packs voice cue text.");
    var packsVoiceCueText = packsVoiceCueProperty!.GetValue(form) as string ?? string.Empty;
    Require(packsVoiceCueText.Contains("Voice cue: import pack", StringComparison.OrdinalIgnoreCase), $"Expected packs voice cue guidance, got '{packsVoiceCueText}'.");
    Require(packsVoiceCueText.Contains("read import again", StringComparison.OrdinalIgnoreCase), $"Expected packs voice cue to mention the import-summary replay route, got '{packsVoiceCueText}'.");
    Require(packsVoiceCueText.Contains("read watch status", StringComparison.OrdinalIgnoreCase), $"Expected packs voice cue to mention the watched-folder readback route, got '{packsVoiceCueText}'.");
    Require(packsVoiceCueText.Contains("review imported packs before enabling", StringComparison.OrdinalIgnoreCase), $"Expected packs voice cue to reinforce review-before-enable guidance, got '{packsVoiceCueText}'.");
}

static void PacksTabExposesImportUpdateAndRollbackButtons()
{
    using var form = new MainForm();
    var tabsField = typeof(MainForm).GetField("_tabs", BindingFlags.Instance | BindingFlags.NonPublic);
    Require(tabsField != null, "MainForm should expose the tab control field for pack discovery.");
    var tabs = tabsField!.GetValue(form) as TabControl;
    Require(tabs != null, "MainForm should build the tab control during construction.");

    var packsTab = tabs!.TabPages.Cast<TabPage>().FirstOrDefault(page => string.Equals(page.Text, "Packs", StringComparison.OrdinalIgnoreCase));
    Require(packsTab != null, "MainForm should include the Packs tab.");
    Require(packsTab!.AllowDrop, "MainForm should let the full Packs tab accept drag-and-drop imports.");
    Require(packsTab.AccessibleDescription?.Contains("drag-and-drop support across the full tab", StringComparison.OrdinalIgnoreCase) == true, $"Expected Packs tab accessibility guidance, got '{packsTab.AccessibleDescription}'.");

    var packButtons = EnumerateControls(packsTab!)
        .OfType<Button>()
        .Select(control => control.Text)
        .ToArray();
    Require(packButtons.Contains("Import Pack...", StringComparer.OrdinalIgnoreCase), $"Expected an Import Pack button on the Packs tab, but found: {string.Join(", ", packButtons)}");
    Require(packButtons.Contains("Import Folder...", StringComparer.OrdinalIgnoreCase), $"Expected an Import Folder button on the Packs tab, but found: {string.Join(", ", packButtons)}");
    Require(packButtons.Contains("Read Import Again", StringComparer.OrdinalIgnoreCase), $"Expected a Read Import Again button on the Packs tab, but found: {string.Join(", ", packButtons)}");
    Require(packButtons.Contains("Update Pack...", StringComparer.OrdinalIgnoreCase), $"Expected an Update Pack button on the Packs tab, but found: {string.Join(", ", packButtons)}");
    Require(packButtons.Contains("Rollback Pack...", StringComparer.OrdinalIgnoreCase), $"Expected a Rollback Pack button on the Packs tab, but found: {string.Join(", ", packButtons)}");
