static void MainFormCanFindReleaseEvidenceFolderFromRepoRoot()
{
    var repoRoot = MainForm.TryGetRepositoryRoot();
    Require(!string.IsNullOrWhiteSpace(repoRoot), "MainForm should be able to find the repository root from the current workspace.");
    Require(Directory.Exists(Path.Combine(repoRoot!, "build")), $"MainForm should find the release evidence build folder under '{repoRoot}'.");

    var evidenceFolder = MainForm.TryGetReleaseEvidenceFolder();
    Require(!string.IsNullOrWhiteSpace(evidenceFolder), "MainForm should be able to find the release evidence folder.");
    Require(string.Equals(evidenceFolder, Path.Combine(repoRoot!, "build"), StringComparison.OrdinalIgnoreCase), $"Expected the release evidence folder to resolve to the repo build folder, got '{evidenceFolder}'.");
}

