    Require(source.Contains("Test-Path -LiteralPath $candidatePath -PathType Leaf", StringComparison.OrdinalIgnoreCase), "Parity evidence script should require local artifact references to be existing files.");
    Require(source.Contains("Get-DuplicateManualEvidenceCheckIds", StringComparison.OrdinalIgnoreCase), "Parity evidence script should detect duplicated manual evidence check ids.");
    Require(source.Contains("parity_categories", StringComparison.OrdinalIgnoreCase), "Parity evidence template should include per-check matrix categories.");
    Require(source.Contains("missing an evidence_command walkthrough prompt", StringComparison.OrdinalIgnoreCase), "Parity evidence script should report missing walkthrough prompts.");
    Require(source.Contains("missing an expected_result proof target", StringComparison.OrdinalIgnoreCase), "Parity evidence script should report missing expected-result proof targets.");
    Require(source.Contains("marked passed but is missing an observed_result", StringComparison.OrdinalIgnoreCase), "Parity evidence script should report passed checks without observed results.");
    Require(source.Contains("marked passed but has no artifact references", StringComparison.OrdinalIgnoreCase), "Parity evidence script should report passed checks without artifacts.");
    Require(source.Contains("marked passed but has invalid or missing local artifact references", StringComparison.OrdinalIgnoreCase), "Parity evidence script should report passed checks with invalid or missing local artifacts.");
    Require(source.Contains("marked passed but has not completed the privacy review checklist", StringComparison.OrdinalIgnoreCase), "Parity evidence script should report passed checks without privacy review.");
    Require(source.Contains("Manual evidence contains duplicate check ids", StringComparison.OrdinalIgnoreCase), "Parity evidence script should report duplicate manual evidence check ids as blockers.");
    Require(source.Contains("description does not match the canonical template", StringComparison.OrdinalIgnoreCase), "Parity evidence script should report stale manual evidence descriptions.");
    Require(source.Contains("evidence_command does not match the canonical template", StringComparison.OrdinalIgnoreCase), "Parity evidence script should report stale manual walkthrough prompts.");
    Require(source.Contains("expected_result does not match the canonical proof target", StringComparison.OrdinalIgnoreCase), "Parity evidence script should report stale expected-result proof targets.");
    Require(source.Contains("show numbers/show grid", StringComparison.OrdinalIgnoreCase), "Parity evidence template should include visible-controls walkthrough instructions.");
    Require(source.Contains("Compare SHA-256 and size", StringComparison.OrdinalIgnoreCase), "Parity evidence template should include public installer hash comparison instructions.");
    Require(source.Contains("Say what can I say", StringComparison.OrdinalIgnoreCase), "Parity evidence template should include command discovery walkthrough instructions.");
    Require(source.Contains("Import a community DLL or folder", StringComparison.OrdinalIgnoreCase), "Parity evidence template should include community extension walkthrough instructions.");
    Require(source.Contains("Load an update manifest", StringComparison.OrdinalIgnoreCase), "Parity evidence template should include update splash walkthrough instructions.");
    Require(source.Contains("Import a community pack", StringComparison.OrdinalIgnoreCase), "Parity evidence template should include import splash walkthrough instructions.");
    Require(source.Contains("Manual evidence local installer hash does not match the current Callsign-Setup.exe", StringComparison.OrdinalIgnoreCase), "Parity evidence script should report remaining hash mismatch proof.");
    Require(source.Contains("Manual evidence website installer hash does not match the current Callsign-Setup.exe", StringComparison.OrdinalIgnoreCase), "Parity evidence script should report website hash mismatch proof.");
    Require(source.Contains("Manual evidence local installer size does not match the current Callsign-Setup.exe", StringComparison.OrdinalIgnoreCase), "Parity evidence script should report local size mismatch proof.");
    Require(source.Contains("Manual evidence website installer size does not match the current Callsign-Setup.exe", StringComparison.OrdinalIgnoreCase), "Parity evidence script should report website size mismatch proof.");
    Require(source.Contains("Clean install from the public website installer", StringComparison.OrdinalIgnoreCase), "Parity evidence script should keep clean-install manual proof explicit.");
    Require(source.Contains("Installed end-to-end automated checks against the built installer and installed runtime", StringComparison.OrdinalIgnoreCase), "Parity evidence script should name installed-runtime proof explicitly.");
    Require(source.Contains("Human-spoken core walkthrough covering wake, identity, overlay/readout, command capture, and visible action", StringComparison.OrdinalIgnoreCase), "Parity evidence script should name human-spoken core proof explicitly.");
    Require(source.Contains("Failure-state walkthrough covering wrong identity, timeout, cancel/reset, microphone/runtime failures, and safe recovery", StringComparison.OrdinalIgnoreCase), "Parity evidence script should name failure-state proof explicitly.");
    Require(source.Contains("Clean Windows user or VM test proving the public installer works without developer state", StringComparison.OrdinalIgnoreCase), "Parity evidence script should name clean-machine proof explicitly.");
    Require(source.Contains("Voice access controls", StringComparison.OrdinalIgnoreCase), "Parity evidence script should enumerate the Voice Access controls category.");
    Require(source.Contains("Correction alternatives", StringComparison.OrdinalIgnoreCase), "Parity evidence script should enumerate dictation correction parity.");
    Require(source.Contains("Safe system/settings control", StringComparison.OrdinalIgnoreCase), "Parity evidence script should enumerate safe settings parity.");
}

static void PrepareReleasePacketScriptPropagatesWebsiteEvidenceMetadata()
{
    var repoRoot = FindRepositoryRoot();
    var scriptPath = Path.Combine(repoRoot, "scripts", "prepare-release-packet.ps1");
    Require(File.Exists(scriptPath), $"Could not find release packet script at {scriptPath}.");

    var source = File.ReadAllText(scriptPath);
    Require(source.Contains("[string]$WebsiteInstallerHash", StringComparison.OrdinalIgnoreCase), "Release packet script should accept the website installer hash.");
    Require(source.Contains("[Int64]$WebsiteInstallerSizeBytes", StringComparison.OrdinalIgnoreCase), "Release packet script should accept the website installer size.");
    Require(source.Contains("'-WebsiteDownloadUrl', $WebsiteDownloadUrl", StringComparison.OrdinalIgnoreCase), "Release packet script should forward the website download URL to parity evidence.");
    Require(source.Contains("'-WebsiteInstallerHash', $WebsiteInstallerHash", StringComparison.OrdinalIgnoreCase), "Release packet script should forward the website installer hash to parity evidence.");
    Require(source.Contains("'-WebsiteInstallerSizeBytes', $WebsiteInstallerSizeBytes", StringComparison.OrdinalIgnoreCase), "Release packet script should forward the website installer size to parity evidence.");
    Require(source.Contains("'-ReleaseMode', $releaseMode", StringComparison.OrdinalIgnoreCase), "Release packet script should forward the release mode to parity evidence.");
    Require(source.Contains("website_installer_sha256 = $WebsiteInstallerHash", StringComparison.OrdinalIgnoreCase), "Release packet script should preserve the website installer hash in its summary.");
    Require(source.Contains("website_installer_size_bytes = $WebsiteInstallerSizeBytes", StringComparison.OrdinalIgnoreCase), "Release packet script should preserve the website installer size in its summary.");
    Require(source.Contains("docs\\downloads\\Callsign-Setup.exe", StringComparison.OrdinalIgnoreCase), "Release packet script should use the generated website installer as local-preview proof.");
    Require(source.Contains("LocalPreviewInstallerPath", StringComparison.OrdinalIgnoreCase), "Release packet script should expose a local-preview installer hash path.");
    Require(source.Contains("Get-FileHash -Algorithm SHA256 -LiteralPath $LocalPreviewInstallerPath", StringComparison.OrdinalIgnoreCase), "Release packet script should hash the generated website installer before falling back to Docker preview inspection.");
    Require(source.Contains("Using generated local website installer for preview proof", StringComparison.OrdinalIgnoreCase), "Release packet script should skip Docker preview setup when the generated website installer already proves the local-preview artifact.");
    Require(source.Contains("release_proof = [pscustomobject]@", StringComparison.OrdinalIgnoreCase), "Release packet script should preserve a compact release-proof object in its summary.");
    Require(source.Contains("comparison_summary = if ([string]::IsNullOrWhiteSpace($WebsiteDownloadUrl))", StringComparison.OrdinalIgnoreCase), "Release packet script should summarize the installer comparison in its summary.");
    Require(source.Contains("update_readback_summary = \"Read Updates Status, Read Check-In Status, Read Visual Status, and Read Restart Proof keep the Updates and visual-contract evidence visible.\"", StringComparison.OrdinalIgnoreCase), "Release packet script should summarize the visible update and visual readback quartet in its summary.");
    Require(source.Contains("release_blocker_summary = if ($null -ne $evidenceReleaseBlockerSummary)", StringComparison.OrdinalIgnoreCase), "Release packet script should carry the compact parity release-blocker summary.");
    Require(source.Contains("manual_checks_remaining_count", StringComparison.OrdinalIgnoreCase), "Release packet script should preserve the remaining manual-check count.");
    Require(source.Contains("manual_categories_missing_count", StringComparison.OrdinalIgnoreCase), "Release packet script should preserve the missing manual-category count.");
    Require(source.Contains("failed_automated_checks_count", StringComparison.OrdinalIgnoreCase), "Release packet script should preserve the failed automated evidence count.");
    Require(source.Contains("blocker_count", StringComparison.OrdinalIgnoreCase), "Release packet script should preserve the release blocker count.");
    Require(source.Contains("next_action", StringComparison.OrdinalIgnoreCase), "Release packet script should preserve the next release-evidence action.");
    Require(source.Contains("Compare the local Callsign-Setup.exe installer to", StringComparison.OrdinalIgnoreCase), "Release packet script should describe the local-vs-website installer comparison.");
    Require(source.Contains("[switch]$LocalPreviewOnly", StringComparison.OrdinalIgnoreCase), "Release packet script should accept the local-preview switch.");
    Require(source.Contains("[switch]$SkipSmoke", StringComparison.OrdinalIgnoreCase), "Release packet script should accept a smoke-skip switch for nested release checks.");
    Require(source.Contains("[switch]$RequireManualEvidence", StringComparison.OrdinalIgnoreCase), "Release packet script should accept a manual-evidence gate.");
    Require(source.Contains("'-SkipSiteBuild'", StringComparison.OrdinalIgnoreCase), "Release packet script should forward the site-build skip switch to the local preview deploy helper.");
    Require(source.Contains("alpha_v1_checklist.ps1", StringComparison.OrdinalIgnoreCase), "Release packet script should invoke the alpha walkthrough checklist.");
    Require(source.Contains("'-RequireManualEvidence'", StringComparison.OrdinalIgnoreCase), "Release packet script should forward the manual-evidence gate to parity evidence.");
    Require(source.Contains("require_manual_evidence = [bool]$RequireManualEvidence", StringComparison.OrdinalIgnoreCase), "Release packet script should record whether the manual-evidence gate was requested.");
    Require(source.Contains("walkthrough_evidence_path = $WalkthroughEvidencePath", StringComparison.OrdinalIgnoreCase), "Release packet script should record the walkthrough evidence path in its summary.");
    Require(source.Contains("release_mode = $releaseMode", StringComparison.OrdinalIgnoreCase), "Release packet script should record the release mode in its summary.");
    Require(source.Contains("packet_status = $packetStatus", StringComparison.OrdinalIgnoreCase), "Release packet script should record packet status in its summary.");
    Require(source.Contains("packet_error = $packetError", StringComparison.OrdinalIgnoreCase), "Release packet script should record packet error details in its summary.");
    Require(source.Contains("$releaseMode = 'local-preview'", StringComparison.OrdinalIgnoreCase), "Release packet script should mark local-preview mode when the Pi is unavailable.");
    Require(source.Contains("release-packet-summary.json", StringComparison.OrdinalIgnoreCase), "Release packet script should write a release summary.");
    Require(source.Contains("New-ReleaseGateSummary", StringComparison.OrdinalIgnoreCase), "Release packet script should preserve the documentation-pack release gates.");
    Require(source.Contains("installed_end_to_end_automated_checks", StringComparison.OrdinalIgnoreCase), "Release packet script should map the installed end-to-end gate to manual evidence.");
    Require(source.Contains("human_spoken_core_walkthrough", StringComparison.OrdinalIgnoreCase), "Release packet script should map the human-spoken walkthrough gate to manual evidence.");
    Require(source.Contains("failure_state_walkthrough", StringComparison.OrdinalIgnoreCase), "Release packet script should map the failure-state walkthrough gate to manual evidence.");
    Require(source.Contains("clean_windows_user_or_vm_test", StringComparison.OrdinalIgnoreCase), "Release packet script should map the clean Windows VM gate to manual evidence.");

    var summaryPath = Path.Combine(repoRoot, "build", "release-packet-summary.json");
    Require(File.Exists(summaryPath), $"Expected release packet summary to exist at {summaryPath}.");
    using var summaryJson = JsonDocument.Parse(File.ReadAllText(summaryPath));
    Require(summaryJson.RootElement.TryGetProperty("release_mode", out var releaseModeProperty), "Release packet summary should include a release_mode field.");
    Require(string.Equals(releaseModeProperty.GetString(), "local-preview", StringComparison.OrdinalIgnoreCase), $"Expected release_mode to be local-preview, got '{releaseModeProperty.GetString()}'.");
    Require(summaryJson.RootElement.TryGetProperty("walkthrough_evidence_path", out var walkthroughEvidencePath), "Release packet summary should include a walkthrough_evidence_path field.");
    var expectedWalkthroughEvidencePath = Path.Combine(repoRoot, "build", "alpha-v1-walkthrough-evidence.json");
    Require(string.Equals(walkthroughEvidencePath.GetString(), expectedWalkthroughEvidencePath, StringComparison.OrdinalIgnoreCase), $"Expected walkthrough_evidence_path to be '{expectedWalkthroughEvidencePath}', got '{walkthroughEvidencePath.GetString()}'.");
    Require(summaryJson.RootElement.TryGetProperty("release_proof", out var releaseProofProperty), "Release packet summary should include a release_proof field.");
    Require(summaryJson.RootElement.TryGetProperty("parity_evidence", out var packetParityEvidenceProperty), "Release packet summary should include parity evidence details.");
    Require(packetParityEvidenceProperty.TryGetProperty("release_blocker_summary", out var packetReleaseBlockerSummary), "Release packet parity evidence should include the compact blocker summary.");
    Require(packetReleaseBlockerSummary.TryGetProperty("blocker_count", out var packetBlockerCount), "Release packet blocker summary should include blocker_count.");
    Require(packetReleaseBlockerSummary.TryGetProperty("next_action", out var packetNextAction), "Release packet blocker summary should include next_action.");
    Require(packetBlockerCount.GetInt32() >= 0, $"Expected non-negative release blocker count, got {packetBlockerCount.GetInt32()}.");
    Require(!string.IsNullOrWhiteSpace(packetNextAction.GetString()), "Release packet blocker summary should include a next action.");
    Require(summaryJson.RootElement.TryGetProperty("release_gates", out var releaseGatesProperty), "Release packet summary should include documentation-pack release gates.");
    var releaseGateIds = releaseGatesProperty.EnumerateArray()
        .Select(gate => gate.TryGetProperty("evidence_check_id", out var id) ? id.GetString() : null)
        .Where(id => !string.IsNullOrWhiteSpace(id))
        .ToArray();
    Require(releaseGateIds.Contains("installed_end_to_end_automated_checks", StringComparer.OrdinalIgnoreCase), "Release packet summary should include the installed end-to-end evidence gate.");
    Require(releaseGateIds.Contains("human_spoken_core_walkthrough", StringComparer.OrdinalIgnoreCase), "Release packet summary should include the human-spoken walkthrough evidence gate.");
    Require(releaseGateIds.Contains("failure_state_walkthrough", StringComparer.OrdinalIgnoreCase), "Release packet summary should include the failure-state walkthrough evidence gate.");
    Require(releaseGateIds.Contains("clean_windows_user_or_vm_test", StringComparer.OrdinalIgnoreCase), "Release packet summary should include the clean Windows VM evidence gate.");
    Require(releaseProofProperty.TryGetProperty("comparison_summary", out var comparisonSummaryProperty), "Release packet summary should include a release proof comparison summary.");
    Require(
        comparisonSummaryProperty.GetString()?.Contains("Compare the local Callsign-Setup.exe installer", StringComparison.OrdinalIgnoreCase) == true
        || comparisonSummaryProperty.GetString()?.Contains("Release proof is waiting for a website download URL", StringComparison.OrdinalIgnoreCase) == true,
        $"Expected release proof comparison summary to describe either the local-versus-website comparison or the missing website URL state, got '{comparisonSummaryProperty.GetString()}'.");
    Require(releaseProofProperty.TryGetProperty("website_installer_sha256", out var websiteHashProperty), "Release packet summary should carry the website installer hash in the release proof block.");
    Require(releaseProofProperty.TryGetProperty("website_installer_size_bytes", out var websiteSizeProperty), "Release packet summary should carry the website installer size in the release proof block.");
    var comparisonReady = comparisonSummaryProperty.GetString()?.Contains("Compare the local Callsign-Setup.exe installer", StringComparison.OrdinalIgnoreCase) == true;
    Require(!comparisonReady || !string.IsNullOrWhiteSpace(websiteHashProperty.GetString()), "Release packet summary should include a website installer hash when comparison proof is ready.");
    Require(!comparisonReady || websiteSizeProperty.GetInt64() > 0, "Release packet summary should include a positive website installer size when comparison proof is ready.");
    Require(releaseProofProperty.TryGetProperty("walkthrough_discovery_summary", out var walkthroughDiscoverySummaryProperty), "Release packet summary should carry the walkthrough discovery summary in the release proof block.");
    Require(walkthroughDiscoverySummaryProperty.GetString()?.Contains("Browser overlay helper discovery", StringComparison.OrdinalIgnoreCase) == true, $"Expected walkthrough discovery summary to mention browser overlay helper discovery, got '{walkthroughDiscoverySummaryProperty.GetString()}'.");
    Require(walkthroughDiscoverySummaryProperty.GetString()?.Contains("Open Checklist", StringComparison.OrdinalIgnoreCase) == true, $"Expected walkthrough discovery summary to mention Open Checklist, got '{walkthroughDiscoverySummaryProperty.GetString()}'.");

    var evidencePath = Path.Combine(repoRoot, "build", "voice-access-parity-evidence.json");
    Require(File.Exists(evidencePath), $"Expected parity evidence to exist at {evidencePath}.");
    using var evidenceJson = JsonDocument.Parse(File.ReadAllText(evidencePath));
    Require(evidenceJson.RootElement.TryGetProperty("release_mode", out var evidenceReleaseMode), "Parity evidence should include a release_mode field.");
    Require(string.Equals(evidenceReleaseMode.GetString(), "local-preview", StringComparison.OrdinalIgnoreCase), $"Expected parity evidence release_mode to be local-preview, got '{evidenceReleaseMode.GetString()}'.");
    Require(evidenceJson.RootElement.TryGetProperty("release_proof", out var evidenceReleaseProof), "Parity evidence should include a release_proof field.");
    Require(evidenceReleaseProof.TryGetProperty("update_readback_summary", out var evidenceUpdateReadbackSummary), "Parity evidence should include the visible update readback summary.");
    Require(evidenceUpdateReadbackSummary.GetString()?.Contains("Read Check-In Status", StringComparison.OrdinalIgnoreCase) == true, $"Expected parity evidence update readback summary to mention check-in status, got '{evidenceUpdateReadbackSummary.GetString()}'.");
    Require(evidenceUpdateReadbackSummary.GetString()?.Contains("Read Visual Status", StringComparison.OrdinalIgnoreCase) == true, $"Expected parity evidence update readback summary to mention visual status, got '{evidenceUpdateReadbackSummary.GetString()}'.");
}

static void PrepareReleasePacketScriptWritesWalkthroughEvidenceChecks()
{
    var repoRoot = FindRepositoryRoot();
    var scriptPath = Path.Combine(repoRoot, "scripts", "prepare-release-packet.ps1");
    var templatePath = Path.Combine(repoRoot, "build", "voice-access-parity-manual-evidence.template.json");
    var summaryPath = Path.Combine(repoRoot, "build", "release-packet-summary.json");

    Require(File.Exists(scriptPath), $"Could not find release packet script at {scriptPath}.");
    var scriptText = File.ReadAllText(scriptPath);
    Require(scriptText.Contains("manual evidence checklist companion", StringComparison.OrdinalIgnoreCase), "Release packet script should validate the manual evidence checklist companion.");

    if (File.Exists(templatePath))
        File.Delete(templatePath);

    var processInfo = new ProcessStartInfo
    {
        FileName = "powershell.exe",
        Arguments = $"-NoProfile -ExecutionPolicy Bypass -File \"{scriptPath}\" -LocalPreviewOnly -WriteManualEvidenceTemplate -RequireWebsiteVerification -SkipSmoke",
        WorkingDirectory = repoRoot,
        UseShellExecute = false,
        RedirectStandardOutput = true,
        RedirectStandardError = true,
        CreateNoWindow = true
    };

    using var process = Process.Start(processInfo);
    Require(process != null, "Release packet script should be startable from the smoke suite.");

    var stdout = process!.StandardOutput.ReadToEnd();
    var stderr = process.StandardError.ReadToEnd();
    process.WaitForExit();

    Require(process.ExitCode == 0, $"Expected release packet template generation to succeed, but it exited {process.ExitCode}. Stdout: {stdout}\nStderr: {stderr}");
    Require(File.Exists(templatePath), $"Expected release packet template at {templatePath}.");
    Require(File.Exists(summaryPath), $"Expected release packet summary at {summaryPath}.");
    var checklistPath = Path.Combine(repoRoot, "build", "voice-access-parity-manual-evidence.checklist.md");
    Require(File.Exists(checklistPath), $"Expected release packet checklist at {checklistPath}.");

    using var summaryJson = JsonDocument.Parse(File.ReadAllText(summaryPath));
    Require(summaryJson.RootElement.TryGetProperty("manual_template_path", out var manualTemplatePath), "Release packet summary should include a manual_template_path field.");
    Require(string.Equals(manualTemplatePath.GetString(), templatePath, StringComparison.OrdinalIgnoreCase), $"Expected release packet summary manual_template_path to be '{templatePath}', got '{manualTemplatePath.GetString()}'.");
    Require(summaryJson.RootElement.TryGetProperty("manual_checklist_path", out var manualChecklistPath), "Release packet summary should include a manual_checklist_path field.");
    Require(string.Equals(manualChecklistPath.GetString(), checklistPath, StringComparison.OrdinalIgnoreCase), $"Expected release packet summary manual_checklist_path to be '{checklistPath}', got '{manualChecklistPath.GetString()}'.");
    Require(summaryJson.RootElement.TryGetProperty("release_proof", out var packetReleaseProof), "Release packet summary should include a release_proof block.");
    Require(packetReleaseProof.TryGetProperty("walkthrough_discovery_summary", out var packetWalkthroughDiscoverySummary), "Release packet summary should include a walkthrough discovery summary in the release proof block.");
    Require(packetWalkthroughDiscoverySummary.GetString()?.Contains("Open Checklist", StringComparison.OrdinalIgnoreCase) == true, $"Expected release packet walkthrough discovery summary to mention Open Checklist, got '{packetWalkthroughDiscoverySummary.GetString()}'.");
    Require(File.ReadAllText(checklistPath).Contains("update_version_match_ignores_installer_hash", StringComparison.OrdinalIgnoreCase), "Release packet checklist should include the version-match installer hash check.");

    using var templateJson = JsonDocument.Parse(File.ReadAllText(templatePath));
    Require(templateJson.RootElement.TryGetProperty("checks", out var checks), "Release packet template should include checks.");
    Require(templateJson.RootElement.TryGetProperty("release_proof", out var releaseProof), "Release packet template should include a release_proof block.");
    Require(releaseProof.TryGetProperty("comparison_summary", out var comparisonSummary), "Release packet template should include a release-proof comparison summary.");
    Require(comparisonSummary.GetString()?.Contains("Compare the local Callsign-Setup.exe installer", StringComparison.OrdinalIgnoreCase) == true, $"Expected release packet template release-proof summary to describe the local-versus-website installer comparison, got '{comparisonSummary.GetString()}'.");
    Require(releaseProof.TryGetProperty("update_readback_summary", out var updateReadbackSummary), "Release packet template should include a visible update readback summary.");
    Require(updateReadbackSummary.GetString()?.Contains("Read Check-In Status", StringComparison.OrdinalIgnoreCase) == true, $"Expected release packet template update readback summary to mention check-in status, got '{updateReadbackSummary.GetString()}'.");
    var checkIds = checks.EnumerateArray()
        .Select(check => check.TryGetProperty("id", out var id) ? id.GetString() : null)
        .Where(id => !string.IsNullOrWhiteSpace(id))
        .ToArray();

    Require(checkIds.Contains("startup_walkthrough_open_release_evidence_action", StringComparer.OrdinalIgnoreCase), "Release packet template should include the startup walkthrough direct Open Release Evidence check.");
    Require(checkIds.Contains("installed_end_to_end_automated_checks", StringComparer.OrdinalIgnoreCase), "Release packet template should include the installed end-to-end automated check.");
    Require(checkIds.Contains("human_spoken_core_walkthrough", StringComparer.OrdinalIgnoreCase), "Release packet template should include the human-spoken core walkthrough check.");
    Require(checkIds.Contains("failure_state_walkthrough", StringComparer.OrdinalIgnoreCase), "Release packet template should include the failure-state walkthrough check.");
    Require(checkIds.Contains("clean_windows_user_or_vm_test", StringComparer.OrdinalIgnoreCase), "Release packet template should include the clean Windows user or VM check.");
    Require(checkIds.Contains("startup_walkthrough_drop_dll_folder_action", StringComparer.OrdinalIgnoreCase), "Release packet template should include the startup walkthrough direct Drop DLL Folder check.");
    Require(checkIds.Contains("open_release_evidence_folder_action", StringComparer.OrdinalIgnoreCase), "Release packet template should include the release evidence folder action check.");
    Require(checkIds.Contains("open_manual_evidence_template_action", StringComparer.OrdinalIgnoreCase), "Release packet template should include the manual evidence template action check.");
    Require(checkIds.Contains("read_check_in_status_voice_command", StringComparer.OrdinalIgnoreCase), "Release packet template should include the visible check-in-status readback check.");
    Require(checkIds.Contains("read_visual_status_voice_command", StringComparer.OrdinalIgnoreCase), "Release packet template should include the visible visual-status readback check.");
    Require(checkIds.Contains("free_parity_paid_gating_walkthrough", StringComparer.OrdinalIgnoreCase), "Release packet template should include the free-parity paid-gating walkthrough check.");
    Require(checkIds.Contains("read_restart_proof_voice_command", StringComparer.OrdinalIgnoreCase), "Release packet template should include the visible restart-proof readback check.");
    Require(checkIds.Contains("update_splash_feature_highlights_walkthrough", StringComparer.OrdinalIgnoreCase), "Release packet template should include the feature-only update splash check.");
    Require(checkIds.Contains("update_version_match_ignores_installer_hash", StringComparer.OrdinalIgnoreCase), "Release packet template should include the version-match installer hash check.");
    Require(checkIds.Contains("public_website_installer_hash_match", StringComparer.OrdinalIgnoreCase), "Release packet template should include the public website installer hash check.");
}

static void VoiceAccessParityEvidenceWritesWalkthroughReleaseEvidenceChecks()
{
    var repoRoot = FindRepositoryRoot();
    var scriptPath = Path.Combine(repoRoot, "scripts", "voice_access_parity_evidence.ps1");
    var templatePath = Path.Combine(repoRoot, "build", "voice-access-parity-manual-evidence.template.json");

    Require(File.Exists(scriptPath), $"Could not find Voice Access parity evidence script at {scriptPath}.");

    if (File.Exists(templatePath))
        File.Delete(templatePath);

    var processInfo = new ProcessStartInfo
    {
        FileName = "powershell.exe",
        Arguments = $"-NoProfile -ExecutionPolicy Bypass -File \"{scriptPath}\" -WriteManualEvidenceTemplate -WebsiteDownloadUrl \"http://localhost:8085/downloads/Callsign-Setup.exe\"",
        WorkingDirectory = repoRoot,
        UseShellExecute = false,
        RedirectStandardOutput = true,
        RedirectStandardError = true,
        CreateNoWindow = true
    };

    using var process = Process.Start(processInfo);
    Require(process != null, "Parity evidence script should be startable from the smoke suite.");

    var stdout = process!.StandardOutput.ReadToEnd();
    var stderr = process.StandardError.ReadToEnd();
    process.WaitForExit();

    Require(process.ExitCode == 0, $"Expected manual-evidence template generation to succeed, but it exited {process.ExitCode}. Stdout: {stdout}\nStderr: {stderr}");
    Require(File.Exists(templatePath), $"Expected manual-evidence template at {templatePath}.");
    var checklistPath = Path.Combine(repoRoot, "build", "voice-access-parity-manual-evidence.checklist.md");
    Require(File.Exists(checklistPath), $"Expected manual-evidence checklist at {checklistPath}.");

    using var templateJson = JsonDocument.Parse(File.ReadAllText(templatePath));
    Require(templateJson.RootElement.TryGetProperty("checks", out var checks), "Manual evidence template should include checks.");
    Require(templateJson.RootElement.TryGetProperty("evidence_header", out var evidenceHeader), "Manual evidence template should include an evidence_header block.");
    Require(evidenceHeader.TryGetProperty("commit", out _), "Manual evidence template header should include commit.");
    Require(evidenceHeader.TryGetProperty("build_id", out _), "Manual evidence template header should include build_id.");
    Require(evidenceHeader.TryGetProperty("artifact_hashes", out var artifactHashes) && artifactHashes.ValueKind == JsonValueKind.Array, "Manual evidence template header should include artifact_hashes.");
    Require(evidenceHeader.TryGetProperty("windows_version_edition_build", out _), "Manual evidence template header should include Windows version/edition/build.");
    Require(evidenceHeader.TryGetProperty("microphone", out _), "Manual evidence template header should include microphone.");
    Require(evidenceHeader.TryGetProperty("wake_identity_transcription_models", out _), "Manual evidence template header should include wake/identity/transcription models.");
    Require(templateJson.RootElement.TryGetProperty("release_proof", out var releaseProof), "Manual evidence template should include a release_proof block.");
    Require(releaseProof.TryGetProperty("comparison_summary", out var comparisonSummary), "Manual evidence template should include a release-proof comparison summary.");
    Require(comparisonSummary.GetString()?.Contains("Compare the local Callsign-Setup.exe installer", StringComparison.OrdinalIgnoreCase) == true, $"Expected manual evidence template release-proof summary to describe the local-versus-website installer comparison, got '{comparisonSummary.GetString()}'.");
    Require(releaseProof.TryGetProperty("update_readback_summary", out var updateReadbackSummary), "Manual evidence template should include a visible update readback summary.");
    Require(updateReadbackSummary.GetString()?.Contains("Read Check-In Status", StringComparison.OrdinalIgnoreCase) == true, $"Expected manual evidence template update readback summary to mention check-in status, got '{updateReadbackSummary.GetString()}'.");
    Require(updateReadbackSummary.GetString()?.Contains("Read Visual Status", StringComparison.OrdinalIgnoreCase) == true, $"Expected manual evidence template update readback summary to mention visual status, got '{updateReadbackSummary.GetString()}'.");

    var checkIds = checks.EnumerateArray()
        .Select(check => check.TryGetProperty("id", out var id) ? id.GetString() : null)
        .Where(id => !string.IsNullOrWhiteSpace(id))
        .ToArray();
    var communityImportCheck = checks.EnumerateArray()
        .FirstOrDefault(check => check.TryGetProperty("id", out var id) && string.Equals(id.GetString(), "community_extension_import_manage", StringComparison.OrdinalIgnoreCase));
    Require(communityImportCheck.ValueKind != JsonValueKind.Undefined, "Manual evidence template should include the community extension walkthrough check.");
    Require(communityImportCheck.TryGetProperty("description", out var communityImportDescription), "Manual evidence template should include a community extension description.");
    Require(communityImportDescription.GetString()?.Contains("Drop DLL Folder", StringComparison.OrdinalIgnoreCase) == true || communityImportDescription.GetString()?.Contains("drop dll folder", StringComparison.OrdinalIgnoreCase) == true, $"Expected community extension description to mention the folder-drop route, got '{communityImportDescription.GetString()}'.");
    Require(communityImportCheck.TryGetProperty("evidence_command", out var communityImportCommand), "Manual evidence template should include a community extension walkthrough command.");
    Require(communityImportCommand.GetString()?.Contains("Drop DLL Folder", StringComparison.OrdinalIgnoreCase) == true || communityImportCommand.GetString()?.Contains("drop dll folder", StringComparison.OrdinalIgnoreCase) == true, $"Expected community extension walkthrough command to mention the folder-drop route, got '{communityImportCommand.GetString()}'.");

    Require(checkIds.Contains("startup_walkthrough_open_release_evidence_action", StringComparer.OrdinalIgnoreCase), "Manual evidence template should include the startup walkthrough direct Open Release Evidence check.");
    Require(checkIds.Contains("installed_end_to_end_automated_checks", StringComparer.OrdinalIgnoreCase), "Manual evidence template should include the installed end-to-end automated check.");
