    Require(checkIds.Contains("read_check_in_status_voice_command", StringComparer.OrdinalIgnoreCase), "Manual evidence template should include the visible check-in-status readback check.");
    Require(checkIds.Contains("read_visual_status_voice_command", StringComparer.OrdinalIgnoreCase), "Manual evidence template should include the visible visual-status readback check.");
    Require(checkIds.Contains("free_parity_paid_gating_walkthrough", StringComparer.OrdinalIgnoreCase), "Manual evidence template should include the free-parity paid-gating walkthrough check.");
    Require(checkIds.Contains("read_restart_proof_voice_command", StringComparer.OrdinalIgnoreCase), "Manual evidence template should include the visible restart-proof readback check.");
    Require(checkIds.Contains("update_splash_feature_highlights_walkthrough", StringComparer.OrdinalIgnoreCase), "Manual evidence template should include the feature-only update splash check.");
    Require(checkIds.Contains("update_version_match_ignores_installer_hash", StringComparer.OrdinalIgnoreCase), "Manual evidence template should include the version-match installer hash check.");
    Require(checkIds.Contains("startup_walkthrough_release_proof_summary", StringComparer.OrdinalIgnoreCase), "Manual evidence template should include the startup walkthrough release-proof summary check.");
    var proofNotesFolder = Path.Combine(repoRoot, "build", "manual-proof-notes");
    Require(Directory.Exists(proofNotesFolder), $"Expected manual proof notes folder at {proofNotesFolder}.");
    var proofNotePaths = Directory.GetFiles(proofNotesFolder, "*.md");
