static void VerifyReleaseReadinessChecksManualEvidenceChecklist()
{
    var repoRoot = FindRepositoryRoot();
    var scriptPath = Path.Combine(repoRoot, "scripts", "verify-release-readiness.ps1");
    Require(File.Exists(scriptPath), $"Could not find release readiness script at {scriptPath}.");
    var scriptText = File.ReadAllText(scriptPath);
    Require(scriptText.Contains("voice-access-parity-manual-evidence.checklist.md", StringComparison.OrdinalIgnoreCase), "Release readiness script should validate the manual evidence checklist companion.");
    Require(scriptText.Contains("callsign.voice_access_parity.manual_evidence.v1", StringComparison.OrdinalIgnoreCase), "Release readiness script should validate the manual evidence template schema.");
    Require(scriptText.Contains("evidence_header", StringComparison.OrdinalIgnoreCase), "Release readiness script should validate the manual evidence template header.");
    Require(scriptText.Contains("at least 40 manual/live checks", StringComparison.OrdinalIgnoreCase), "Release readiness script should validate the manual evidence template check count.");
    Require(scriptText.Contains("at least 40 check sections", StringComparison.OrdinalIgnoreCase), "Release readiness script should validate the manual evidence checklist section count.");
    Require(scriptText.Contains("Generated manual evidence checklist is missing required release-proof fields", StringComparison.OrdinalIgnoreCase), "Release readiness script should validate required checklist release-proof fields.");
    Require(scriptText.Contains("manual-proof-notes", StringComparison.OrdinalIgnoreCase), "Release readiness script should validate the manual proof-note folder companion.");
    Require(scriptText.Contains("at least 40 markdown notes", StringComparison.OrdinalIgnoreCase), "Release readiness script should require all manual proof-note files.");
    Require(scriptText.Contains("required evidence sections", StringComparison.OrdinalIgnoreCase), "Release readiness script should validate the required proof-note evidence sections.");
    Require(scriptText.Contains("## Evidence Command", StringComparison.OrdinalIgnoreCase), "Release readiness script should require proof notes to include evidence-command sections.");
    Require(scriptText.Contains("## Privacy Review", StringComparison.OrdinalIgnoreCase), "Release readiness script should require proof notes to include privacy-review sections.");
    Require(scriptText.Contains("## Release Recommendation", StringComparison.OrdinalIgnoreCase), "Release readiness script should require proof notes to include release-recommendation sections.");
    Require(scriptText.Contains("manual checklist companion", StringComparison.OrdinalIgnoreCase) || scriptText.Contains("manual evidence checklist", StringComparison.OrdinalIgnoreCase), "Release readiness script should describe the manual checklist validation.");
    Require(scriptText.Contains("downloads\\Callsign-Setup.exe", StringComparison.OrdinalIgnoreCase), "Release readiness script should verify the generated local website installer path without requiring a large localhost HTTP download.");
    Require(scriptText.Contains("LocalPreviewInstallerPath", StringComparison.OrdinalIgnoreCase), "Release readiness script should expose a local-preview installer hash path.");
    Require(scriptText.Contains("Verifying local website preview installer", StringComparison.OrdinalIgnoreCase), "Release readiness script should report local preview installer hash verification.");
}

static void VerifyReleaseReadinessRequiresWebsiteProofWhenRequested()
{
    var repoRoot = FindRepositoryRoot();
    var scriptPath = Path.Combine(repoRoot, "scripts", "verify-release-readiness.ps1");
    var tempRoot = Path.Combine(Path.GetTempPath(), "Callsign.AlphaSmoke.ReadinessProof", Guid.NewGuid().ToString("N"));

    Require(File.Exists(scriptPath), $"Could not find release readiness script at {scriptPath}.");
    var scriptText = File.ReadAllText(scriptPath);
    Require(scriptText.Contains("Website verification is required", StringComparison.OrdinalIgnoreCase), "Release readiness script should hard-fail when required website verification has no reachable proof target.");
    Require(scriptText.Contains("Release readiness blocked by required checks", StringComparison.OrdinalIgnoreCase), "Release readiness script should preserve the required-checks blocker message.");

    Directory.CreateDirectory(tempRoot);
    try
    {
        var processInfo = new ProcessStartInfo
        {
            FileName = "powershell.exe",
            Arguments = $"-NoProfile -ExecutionPolicy Bypass -File \"{scriptPath}\" -Root \"{tempRoot}\" -SkipBuild -SkipSiteBuild -RequireWebsiteVerification",
            WorkingDirectory = repoRoot,
            UseShellExecute = false,
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            CreateNoWindow = true
        };

        using var process = Process.Start(processInfo);
        Require(process != null, "Release readiness script should be startable from the smoke suite.");

        var stdout = process!.StandardOutput.ReadToEnd();
        var stderr = process.StandardError.ReadToEnd();
        process.WaitForExit();

        Require(process.ExitCode != 0, $"Expected strict release readiness without a verifiable installer/download target to fail, but it exited 0. Stdout: {stdout}\nStderr: {stderr}");
        Require(
            stdout.Contains("Release readiness blocked by required checks", StringComparison.OrdinalIgnoreCase)
            || stdout.Contains("Website verification is required", StringComparison.OrdinalIgnoreCase)
            || stdout.Contains("Local installer hash unavailable", StringComparison.OrdinalIgnoreCase),
            $"Expected strict readiness output to explain the missing required website proof. Stdout: {stdout}\nStderr: {stderr}");
    }
    finally
    {
        try
        {
            if (Directory.Exists(tempRoot))
                Directory.Delete(tempRoot, recursive: true);
        }
        catch
        {
        }
    }
}

static void PrepareReleasePacketScriptLeavesFailureSummaryWhenManualEvidenceIsMissing()
{
    var repoRoot = FindRepositoryRoot();
    var scriptPath = Path.Combine(repoRoot, "scripts", "prepare-release-packet.ps1");
    var templatePath = Path.Combine(repoRoot, "build", "voice-access-parity-manual-evidence.template.json");
    var summaryPath = Path.Combine(repoRoot, "build", "release-packet-summary.json");

    Require(File.Exists(scriptPath), $"Could not find release packet script at {scriptPath}.");
    Require(File.Exists(templatePath), $"Could not find the generated manual evidence template at {templatePath}.");

    var processInfo = new ProcessStartInfo
    {
        FileName = "powershell.exe",
        Arguments = $"-NoProfile -ExecutionPolicy Bypass -File \"{scriptPath}\" -LocalPreviewOnly -RequireWebsiteVerification -RequireManualEvidence -ManualEvidencePath \"{templatePath}\"",
        WorkingDirectory = repoRoot,
        UseShellExecute = false,
        RedirectStandardOutput = true,
        RedirectStandardError = true,
        CreateNoWindow = true
    };

    using var process = Process.Start(processInfo);
    Require(process != null, "Release packet script should be startable from the smoke suite.");

    var stdout = process!.StandardOutput.ReadToEnd();
    var stderr = process.StandardError.ReadToEnd();
    process.WaitForExit();

    Require(process.ExitCode != 0, $"Expected strict release packet run with template evidence to fail, but it exited 0. Stdout: {stdout}\nStderr: {stderr}");
    Require(File.Exists(summaryPath), $"Expected strict release packet run to leave a summary at {summaryPath}.");

    using var summaryJson = JsonDocument.Parse(File.ReadAllText(summaryPath));
    Require(summaryJson.RootElement.TryGetProperty("packet_status", out var packetStatus), "Release packet summary should include a packet_status field.");
    Require(string.Equals(packetStatus.GetString(), "failed", StringComparison.OrdinalIgnoreCase), $"Expected packet_status to be failed, got '{packetStatus.GetString()}'.");
    Require(summaryJson.RootElement.TryGetProperty("packet_error", out var packetError), "Release packet summary should include a packet_error field.");
    Require(!string.IsNullOrWhiteSpace(packetError.GetString()), "Release packet summary should include packet error details.");
    Require(summaryJson.RootElement.TryGetProperty("require_manual_evidence", out var requireManualEvidence), "Release packet summary should include the manual-evidence gate flag.");
    Require(requireManualEvidence.GetBoolean(), "Release packet summary should mark the strict manual-evidence gate as requested.");
    Require(summaryJson.RootElement.TryGetProperty("parity_evidence", out var parityEvidence), "Release packet summary should include parity evidence details.");
    Require(parityEvidence.TryGetProperty("release_ready", out var releaseReady), "Release packet summary should include parity release readiness.");
    Require(!releaseReady.GetBoolean(), "Strict packet run with the template should not report release readiness.");
}

static void PrepareReleasePacketScriptLeavesFailureSummaryOnMissingRoot()
{
    var repoRoot = FindRepositoryRoot();
    var scriptPath = Path.Combine(repoRoot, "scripts", "prepare-release-packet.ps1");
