static void WakeCandidateStatusReportsMargin()
{
    var method = typeof(MainForm).GetMethod("FormatWakeCandidateStatus", BindingFlags.NonPublic | BindingFlags.Static);
    Require(method != null, "Wake candidate formatter should remain available for overlay status text.");
    var formatMethod = method ?? throw new InvalidOperationException("Wake candidate formatter should remain available for overlay status text.");

    var accepted = (string?)formatMethod.Invoke(null, new object?[] { "Callsign", 0.021, 0.01 }) ?? throw new InvalidOperationException("Wake candidate formatter should return accepted wake text.");
    Require(accepted.Contains("margin +1.1%", StringComparison.OrdinalIgnoreCase), $"Expected wake candidate status to report score margin, got '{accepted}'.");
    Require(accepted.Contains("heard 'Callsign'", StringComparison.OrdinalIgnoreCase), $"Expected wake candidate status to name the candidate, got '{accepted}'.");
    Require(accepted.Contains("Next: say Callsign", StringComparison.OrdinalIgnoreCase), $"Expected wake candidate status to include the next step after acceptance, got '{accepted}'.");

    var waiting = (string?)formatMethod.Invoke(null, new object?[] { "Callsign", 0.008, 0.01 }) ?? throw new InvalidOperationException("Wake candidate formatter should return waiting wake text.");
    Require(waiting.Contains("margin -0.2%", StringComparison.OrdinalIgnoreCase) || waiting.Contains("margin -0.1%", StringComparison.OrdinalIgnoreCase), $"Expected wake candidate status to report a negative margin, got '{waiting}'.");
    Require(waiting.Contains("listening for Callsign", StringComparison.OrdinalIgnoreCase), $"Expected wake candidate status to explain the waiting state, got '{waiting}'.");
    Require(waiting.Contains("Next: speak closer to the microphone or re-run wake calibration", StringComparison.OrdinalIgnoreCase), $"Expected wake candidate status to include a recovery hint, got '{waiting}'.");

    using var form = new MainForm();
    var marginProperty = typeof(MainForm).GetProperty("WakeMarginText", BindingFlags.Instance | BindingFlags.Public);
    Require(marginProperty != null, "MainForm should expose the wake margin text.");
    var wakeMarginText = marginProperty!.GetValue(form) as string ?? string.Empty;
    Require(wakeMarginText.Contains("Wake margin", StringComparison.OrdinalIgnoreCase), $"Expected wake margin label text, got '{wakeMarginText}'.");
}

static void WakeReliabilityLineHighlightsNextVisibleAction()
{
    var method = typeof(MainForm).GetMethod("BuildWakeReliabilityText", BindingFlags.NonPublic | BindingFlags.Static);
    Require(method != null, "Wake reliability formatter should remain available for session status text.");
    var formatMethod = method ?? throw new InvalidOperationException("Wake reliability formatter should remain available for session status text.");

    var unavailable = (string?)formatMethod.Invoke(null, new object?[] { null, null, false, 0 }) ?? throw new InvalidOperationException("Wake reliability formatter should return unavailable wake text.");
    Require(unavailable.Contains("Wake detector unavailable", StringComparison.OrdinalIgnoreCase), $"Expected unavailable wake text, got '{unavailable}'.");

    var waiting = (string?)formatMethod.Invoke(null, new object?[] { "openWakeWord", "none", false, 3 }) ?? throw new InvalidOperationException("Wake reliability formatter should return waiting wake text.");
    Require(waiting.Contains("Current wake detector: openWakeWord", StringComparison.OrdinalIgnoreCase), $"Expected current detector text, got '{waiting}'.");
    Require(waiting.Contains("Last wake source: none", StringComparison.OrdinalIgnoreCase), $"Expected wake source text, got '{waiting}'.");
    Require(waiting.Contains("Samples: 3", StringComparison.OrdinalIgnoreCase), $"Expected wake reliability text to show sample count, got '{waiting}'.");
    Require(waiting.Contains("Next: say Callsign to wake", StringComparison.OrdinalIgnoreCase), $"Expected next visible action text, got '{waiting}'.");

    var accepted = (string?)formatMethod.Invoke(null, new object?[] { "openWakeWord", "audio-wake-detector", true, 3 }) ?? throw new InvalidOperationException("Wake reliability formatter should return accepted wake text.");
    Require(accepted.Contains("Wake accepted by openWakeWord", StringComparison.OrdinalIgnoreCase), $"Expected accepted wake text, got '{accepted}'.");
    Require(accepted.Contains("Last wake source: audio-wake-detector", StringComparison.OrdinalIgnoreCase), $"Expected accepted wake source text, got '{accepted}'.");
    Require(accepted.Contains("Samples: 3", StringComparison.OrdinalIgnoreCase), $"Expected accepted wake text to show sample count, got '{accepted}'.");
    Require(accepted.Contains("Next: verify identity", StringComparison.OrdinalIgnoreCase), $"Expected accepted wake next step, got '{accepted}'.");

    using var form = new MainForm();
    var reliabilityProperty = typeof(MainForm).GetProperty("WakeReliabilityText", BindingFlags.Instance | BindingFlags.Public);
    Require(reliabilityProperty != null, "MainForm should expose the wake reliability text.");
    var wakeReliabilityText = reliabilityProperty!.GetValue(form) as string ?? string.Empty;
    Require(!string.IsNullOrWhiteSpace(wakeReliabilityText), "Wake reliability text should not be empty.");
    Require(wakeReliabilityText.Contains("Wake", StringComparison.OrdinalIgnoreCase), $"Expected visible wake reliability text, got '{wakeReliabilityText}'.");
}

static void VisibleControlsOverlayShowsFocusedTarget()
{
    using var overlay = new VisibleControlsOverlayForm();
    var annotations = new[]
    {
        new VisibleControlOverlayAnnotation(1, new Rectangle(10, 10, 100, 30), "Active account", false),
        new VisibleControlOverlayAnnotation(2, new Rectangle(10, 50, 100, 30), "Voice", true),
        new VisibleControlOverlayAnnotation(3, new Rectangle(10, 90, 100, 30), "Session", false)
    };

    overlay.ShowOverlay(
        new Rectangle(0, 0, 800, 600),
        "Visible controls for Setup",
        "Voice cue: Hearing your command...",
        "Heard: open notepad",
        new[] { "1. Active account", "2. Voice", "3. Session" },
        annotations,
        "Scope: Callsign setup");

    Require(overlay.FocusText.Contains("Focused: 2. Voice", StringComparison.OrdinalIgnoreCase), $"Expected focus label to show focused control, got '{overlay.FocusText}'.");
