    Require(AlphaCommandRouter.TryRoute("prefill manual evidence", out var prefillManualEvidenceRoute), "Prefill manual evidence should route.");
    Require(prefillManualEvidenceRoute.Target == "ui-create-evidence-draft", $"Expected ui-create-evidence-draft target for prefill manual evidence, got '{prefillManualEvidenceRoute.Target}'.");
    Require(AlphaCommandRouter.TryRoute("open evidence draft", out var openEvidenceDraftRoute), "Open evidence draft should route.");
    Require(openEvidenceDraftRoute.Kind == AlphaCommandKind.UiAction, "Open evidence draft should be a UI action.");
    Require(openEvidenceDraftRoute.Target == "ui-open-evidence-draft", $"Expected ui-open-evidence-draft target, got '{openEvidenceDraftRoute.Target}'.");
    Require(AlphaCommandRouter.TryRoute("open manual evidence draft", out var openManualEvidenceDraftRoute), "Open manual evidence draft should route.");
    Require(openManualEvidenceDraftRoute.Target == "ui-open-evidence-draft", $"Expected ui-open-evidence-draft target for open manual evidence draft, got '{openManualEvidenceDraftRoute.Target}'.");
    Require(AlphaCommandRouter.TryRoute("read evidence draft", out var readEvidenceDraftRoute), "Read evidence draft should route.");
    Require(readEvidenceDraftRoute.Kind == AlphaCommandKind.UiAction, "Read evidence draft should be a UI action.");
    Require(readEvidenceDraftRoute.Target == "ui-read-evidence-draft", $"Expected ui-read-evidence-draft target, got '{readEvidenceDraftRoute.Target}'.");
    Require(AlphaCommandRouter.TryRoute("what remains in the evidence draft", out var evidenceDraftRemainingRoute), "Evidence draft remaining question should route.");
    Require(evidenceDraftRemainingRoute.Target == "ui-read-evidence-draft", $"Expected ui-read-evidence-draft target for draft remaining, got '{evidenceDraftRemainingRoute.Target}'.");
    Require(AlphaCommandRouter.TryRoute("read proof notes", out var readProofNotesRoute), "Read proof notes should route.");
    Require(readProofNotesRoute.Kind == AlphaCommandKind.UiAction, "Read proof notes should be a UI action.");
    Require(readProofNotesRoute.Target == "ui-read-proof-notes-status", $"Expected ui-read-proof-notes-status target, got '{readProofNotesRoute.Target}'.");
    Require(AlphaCommandRouter.TryRoute("what proof notes exist", out var whatProofNotesExistRoute), "What proof notes exist should route.");
    Require(whatProofNotesExistRoute.Target == "ui-read-proof-notes-status", $"Expected ui-read-proof-notes-status target for proof notes status, got '{whatProofNotesExistRoute.Target}'.");
    Require(AlphaCommandRouter.TryRoute("read visual status", out var readVisualStatusRoute), "Read visual status should route.");
    Require(readVisualStatusRoute.Kind == AlphaCommandKind.UiAction, "Read visual status should be a UI action.");
    Require(readVisualStatusRoute.Target == "ui-read-visual-status", $"Expected ui-read-visual-status target, got '{readVisualStatusRoute.Target}'.");
    Require(AlphaCommandRouter.TryRoute("read visual polish status", out var readVisualPolishStatusRoute), "Read visual polish status should route.");
    Require(readVisualPolishStatusRoute.Target == "ui-read-visual-status", $"Expected visual-polish alias to route to ui-read-visual-status, got '{readVisualPolishStatusRoute.Target}'.");
    Require(AlphaCommandRouter.TryRoute("read accessibility mode", out var readAccessibilityModeRoute), "Read accessibility mode should route.");
    Require(readAccessibilityModeRoute.Target == "ui-read-visual-status", $"Expected accessibility-mode alias to route to ui-read-visual-status, got '{readAccessibilityModeRoute.Target}'.");
    Require(AlphaCommandRouter.TryRoute("read high contrast status", out var readHighContrastStatusRoute), "Read high contrast status should route.");
    Require(readHighContrastStatusRoute.Target == "ui-read-visual-status", $"Expected high-contrast alias to route to ui-read-visual-status, got '{readHighContrastStatusRoute.Target}'.");
    Require(AlphaCommandRouter.TryRoute("read text scale status", out var readTextScaleStatusRoute), "Read text scale status should route.");
    Require(readTextScaleStatusRoute.Target == "ui-read-visual-status", $"Expected text-scale alias to route to ui-read-visual-status, got '{readTextScaleStatusRoute.Target}'.");
    Require(AlphaCommandRouter.TryRoute("read reduced motion status", out var readReducedMotionStatusRoute), "Read reduced motion status should route.");
    Require(readReducedMotionStatusRoute.Target == "ui-read-visual-status", $"Expected reduced-motion alias to route to ui-read-visual-status, got '{readReducedMotionStatusRoute.Target}'.");
    Require(AlphaCommandRouter.TryRoute("read restart proof", out var readRestartProofRoute), "Read restart proof should route.");
    Require(readRestartProofRoute.Kind == AlphaCommandKind.UiAction, "Read restart proof should be a UI action.");
    Require(readRestartProofRoute.Target == "ui-read-restart-proof", $"Expected ui-read-restart-proof target, got '{readRestartProofRoute.Target}'.");
    Require(AlphaCommandRouter.TryRoute("read release proof", out var readReleaseProofRoute), "Read release proof should route.");
    Require(readReleaseProofRoute.Kind == AlphaCommandKind.UiAction, "Read release proof should be a UI action.");
    Require(readReleaseProofRoute.Target == "ui-read-release-proof", $"Expected ui-read-release-proof target, got '{readReleaseProofRoute.Target}'.");
    Require(AlphaCommandRouter.TryRoute("read voice mode status", out var readVoiceModeStatusRoute), "Read voice mode status should route.");
    Require(readVoiceModeStatusRoute.Kind == AlphaCommandKind.UiAction, "Read voice mode status should be a UI action.");
    Require(readVoiceModeStatusRoute.Target == "ui-read-voice-mode-status", $"Expected ui-read-voice-mode-status target, got '{readVoiceModeStatusRoute.Target}'.");
    Require(AlphaCommandRouter.TryRoute("read watch status", out var readWatchStatusRoute), "Read watch status should route.");
    Require(readWatchStatusRoute.Kind == AlphaCommandKind.UiAction, "Read watch status should be a UI action.");
    Require(readWatchStatusRoute.Target == "ui-read-watch-status", $"Expected ui-read-watch-status target, got '{readWatchStatusRoute.Target}'.");
    Require(AlphaCommandRouter.TryRoute("restart proof", out var restartProofRoute), "Restart proof should route.");
    Require(restartProofRoute.Kind == AlphaCommandKind.UiAction, "Restart proof should be a UI action.");
    Require(restartProofRoute.Target == "ui-read-restart-proof", $"Expected restart proof to route to ui-read-restart-proof, got '{restartProofRoute.Target}'.");

    Require(AlphaCommandRouter.TryRoute("commands only mode", out var commandsOnlyModeRoute), "Commands-only mode command should route.");
    Require(commandsOnlyModeRoute.Kind == AlphaCommandKind.UiAction, "Commands-only mode should be a UI action.");
    Require(commandsOnlyModeRoute.Target == "ui-set-voice-mode:commands", $"Expected ui-set-voice-mode:commands target, got '{commandsOnlyModeRoute.Target}'.");
    Require(AlphaCommandRouter.TryRoute("start command mode", out var startCommandModeRoute), "Start command mode should route.");
    Require(startCommandModeRoute.Target == "ui-set-voice-mode:commands", $"Expected ui-set-voice-mode:commands target, got '{startCommandModeRoute.Target}'.");
    Require(AlphaCommandRouter.TryRoute("turn off dictation mode", out var turnOffDictationModeRoute), "Turn off dictation mode should route to commands-only mode.");
    Require(turnOffDictationModeRoute.Target == "ui-set-voice-mode:commands", $"Expected ui-set-voice-mode:commands target, got '{turnOffDictationModeRoute.Target}'.");

    Require(AlphaCommandRouter.TryRoute("dictation mode", out var dictationModeRoute), "Dictation mode command should route.");
    Require(dictationModeRoute.Kind == AlphaCommandKind.UiAction, "Dictation mode should be a UI action.");
    Require(dictationModeRoute.Target == "ui-set-voice-mode:dictation", $"Expected ui-set-voice-mode:dictation target, got '{dictationModeRoute.Target}'.");
    Require(AlphaCommandRouter.TryRoute("start dictation mode", out var startDictationModeRoute), "Start dictation mode should route.");
    Require(startDictationModeRoute.Target == "ui-set-voice-mode:dictation", $"Expected ui-set-voice-mode:dictation target, got '{startDictationModeRoute.Target}'.");
    Require(AlphaCommandRouter.TryRoute("typing mode", out var typingModeRoute), "Typing mode should route.");
    Require(typingModeRoute.Target == "ui-set-voice-mode:dictation", $"Expected ui-set-voice-mode:dictation target, got '{typingModeRoute.Target}'.");

    Require(AlphaCommandRouter.TryRoute("default mode", out var defaultModeRoute), "Default mode command should route.");
    Require(defaultModeRoute.Kind == AlphaCommandKind.UiAction, "Default mode should be a UI action.");
    Require(defaultModeRoute.Target == "ui-set-voice-mode:default", $"Expected ui-set-voice-mode:default target, got '{defaultModeRoute.Target}'.");
    Require(AlphaCommandRouter.TryRoute("commands plus dictation mode", out var commandsPlusDictationModeRoute), "Commands plus dictation mode should route.");
    Require(commandsPlusDictationModeRoute.Target == "ui-set-voice-mode:default", $"Expected ui-set-voice-mode:default target, got '{commandsPlusDictationModeRoute.Target}'.");

    foreach (var phrase in new[] { "voice access wake up", "wake up", "microphone on", "unmute microphone" })
    {
        Require(AlphaCommandRouter.TryRoute(phrase, out var startListeningRoute), $"Voice Access-style start-listening phrase should route: {phrase}");
        Require(startListeningRoute.Kind == AlphaCommandKind.UiAction, $"Start-listening phrase should be a UI action: {phrase}");
        Require(startListeningRoute.Target == "ui-start-listening", $"Expected ui-start-listening for '{phrase}', got '{startListeningRoute.Target}'.");
    }

    foreach (var phrase in new[] { "voice access sleep", "go to sleep", "turn off microphone", "turn off voice access", "stop voice access", "close voice access", "exit voice access", "quit voice access", "mute microphone", "microphone off" })
    {
        Require(AlphaCommandRouter.TryRoute(phrase, out var stopListeningRoute), $"Voice Access-style stop-listening phrase should route: {phrase}");
        Require(stopListeningRoute.Kind == AlphaCommandKind.UiAction, $"Stop-listening phrase should be a UI action: {phrase}");
        Require(stopListeningRoute.Target == "ui-stop-listening", $"Expected ui-stop-listening for '{phrase}', got '{stopListeningRoute.Target}'.");
        Require(AlphaVoiceTranscriptParser.IsStopListeningCommand(phrase), $"Stop-listening phrase should be accepted by transcript-level listener guard: {phrase}");
    }

    foreach (var phrase in new[] { "stop", "stop now", "pause", "cancel", "never mind" })
    {
        Require(AlphaCommandRouter.TryRoute(phrase, out var cancelRoute), $"Urgent session-safety phrase should route: {phrase}");
        Require(cancelRoute.Kind == AlphaCommandKind.UiAction, $"Urgent session-safety phrase should be a UI action: {phrase}");
        Require(cancelRoute.Target == "ui-cancel-session", $"Expected ui-cancel-session for '{phrase}', got '{cancelRoute.Target}'.");
        Require(AlphaVoiceTranscriptParser.IsCancelCommand(phrase), $"Urgent session-safety phrase should be recognized before command execution: {phrase}");
    }

    foreach (var phrase in new[] { "reset session", "restart session", "clear session" })
    {
        Require(AlphaCommandRouter.TryRoute(phrase, out var resetRoute), $"Reset-session phrase should route: {phrase}");
        Require(resetRoute.Kind == AlphaCommandKind.UiAction, $"Reset-session phrase should be a UI action: {phrase}");
        Require(resetRoute.Target == "ui-reset-session", $"Expected ui-reset-session for '{phrase}', got '{resetRoute.Target}'.");
    }

    Require(AlphaCommandRouter.TryRoute("close active app", out var closeWindowRoute), "Close active app command should route.");
    Require(closeWindowRoute.Kind == AlphaCommandKind.SystemControl, "Close active app should be a system-control action.");
    Require(closeWindowRoute.Target == "system-close-window", $"Expected system-close-window target, got '{closeWindowRoute.Target}'.");
    Require(AlphaCommandRouter.TryRoute("press alt f4", out var altF4Route), "Alt+F4 close command should route.");
    Require(altF4Route.Kind == AlphaCommandKind.SystemControl, "Alt+F4 should be a system-control action.");
    Require(altF4Route.Target == "system-close-window", $"Expected system-close-window target, got '{altF4Route.Target}'.");

    var parsed = AlphaVoiceIntentParser.ParseVerifiedTranscript("Callsign echo one what can I say", "Callsign", "echo one");
    Require(parsed.Kind == AlphaVoiceIntentKind.UiAction, $"Expected UiAction, got {parsed.Kind}.");
    Require(parsed.Target == "ui-voice-help", $"Expected ui-voice-help target, got '{parsed.Target}'.");

    var settingsIntent = AlphaVoiceIntentParser.ParseVerifiedTranscript("Callsign echo one open voice access settings", "Callsign", "echo one");
    Require(settingsIntent.Kind == AlphaVoiceIntentKind.UiNavigation, $"Expected UiNavigation for settings intent, got {settingsIntent.Kind}.");
    Require(settingsIntent.Target == "Voice", $"Expected Voice target for settings intent, got '{settingsIntent.Target}'.");

    var guideIntent = AlphaVoiceIntentParser.ParseVerifiedTranscript("Callsign echo one open voice access guide", "Callsign", "echo one");
    Require(guideIntent.Kind == AlphaVoiceIntentKind.UiAction, $"Expected UiAction for guide intent, got {guideIntent.Kind}.");
    Require(guideIntent.Target == "ui-getting-started", $"Expected ui-getting-started target for guide intent, got '{guideIntent.Target}'.");

    var sleepIntent = AlphaVoiceIntentParser.ParseVerifiedTranscript("Callsign echo one go to sleep", "Callsign", "echo one");
    Require(sleepIntent.Kind == AlphaVoiceIntentKind.UiAction, $"Expected UiAction for sleep intent, got {sleepIntent.Kind}.");
    Require(sleepIntent.Target == "ui-stop-listening", $"Expected ui-stop-listening sleep target, got '{sleepIntent.Target}'.");
    var stopNowIntent = AlphaVoiceIntentParser.ParseVerifiedTranscript("Callsign echo one stop now", "Callsign", "echo one");
    Require(stopNowIntent.Kind == AlphaVoiceIntentKind.UiAction, $"Expected UiAction for stop-now intent, got {stopNowIntent.Kind}.");
    Require(stopNowIntent.Target == "ui-cancel-session", $"Expected ui-cancel-session stop-now target, got '{stopNowIntent.Target}'.");
    var resetIntent = AlphaVoiceIntentParser.ParseVerifiedTranscript("Callsign echo one reset session", "Callsign", "echo one");
    Require(resetIntent.Kind == AlphaVoiceIntentKind.UiAction, $"Expected UiAction for reset-session intent, got {resetIntent.Kind}.");
    Require(resetIntent.Target == "ui-reset-session", $"Expected ui-reset-session target, got '{resetIntent.Target}'.");
    var restartIntent = AlphaVoiceIntentParser.ParseVerifiedTranscript("Callsign echo one restart listening", "Callsign", "echo one");
    Require(restartIntent.Kind == AlphaVoiceIntentKind.UiAction, $"Expected UiAction for restart-listening intent, got {restartIntent.Kind}.");
    Require(restartIntent.Target == "ui-restart-listening", $"Expected ui-restart-listening target, got '{restartIntent.Target}'.");

    var parsedMode = AlphaVoiceIntentParser.ParseVerifiedTranscript("Callsign echo one switch to commands only mode", "Callsign", "echo one");
    Require(parsedMode.Kind == AlphaVoiceIntentKind.UiAction, $"Expected UiAction for voice mode, got {parsedMode.Kind}.");
    Require(parsedMode.Target == "ui-set-voice-mode:commands", $"Expected ui-set-voice-mode:commands target, got '{parsedMode.Target}'.");
    var startCommandMode = AlphaVoiceIntentParser.ParseVerifiedTranscript("Callsign echo one start command mode", "Callsign", "echo one");
    Require(startCommandMode.Kind == AlphaVoiceIntentKind.UiAction, $"Expected UiAction for start command mode, got {startCommandMode.Kind}.");
    Require(startCommandMode.Target == "ui-set-voice-mode:commands", $"Expected ui-set-voice-mode:commands target, got '{startCommandMode.Target}'.");
    var startDictationMode = AlphaVoiceIntentParser.ParseVerifiedTranscript("Callsign echo one start dictation mode", "Callsign", "echo one");
    Require(startDictationMode.Kind == AlphaVoiceIntentKind.UiAction, $"Expected UiAction for start dictation mode, got {startDictationMode.Kind}.");
    Require(startDictationMode.Target == "ui-set-voice-mode:dictation", $"Expected ui-set-voice-mode:dictation target, got '{startDictationMode.Target}'.");
    var defaultPlusDictationMode = AlphaVoiceIntentParser.ParseVerifiedTranscript("Callsign echo one commands plus dictation mode", "Callsign", "echo one");
    Require(defaultPlusDictationMode.Kind == AlphaVoiceIntentKind.UiAction, $"Expected UiAction for commands plus dictation mode, got {defaultPlusDictationMode.Kind}.");
    Require(defaultPlusDictationMode.Target == "ui-set-voice-mode:default", $"Expected ui-set-voice-mode:default target, got '{defaultPlusDictationMode.Target}'.");
}

static void CommandDiscoveryListsBuiltInAndExtensionCommands()
{
    var registry = PackTestSupport.CreateRegistry();
    var import = registry.ImportPack(typeof(SampleCommandPack).Assembly.Location);
    Require(import.Succeeded, $"Community pack import should succeed: {import.Message}");

    var commands = CommandDiscoveryService.GetCommands(registry);
    Require(commands.Any(command => command.Phrase == "what can I say"), "Command discovery should include the help command.");
    Require(commands.Any(command => command.Category == "Help" && command.Phrase == "what can I say" && command.Examples?.Contains("close commands") == true && command.Examples.Contains("cancel commands")), "Command discovery should include command-palette dismissal commands.");
    Require(commands.Any(command => command.Category == "Help" && command.Phrase == "what can I say" && command.Examples?.Contains("show system commands") == true && command.Examples.Contains("show free commands")), "Command discovery should include quick voice-help filter commands.");
    Require(commands.Any(command => command.Category == "Updates" && command.Phrase == "close update splash" && command.Examples?.Contains("dismiss update splash") == true && command.Examples.Contains("cancel update splash")), "Command discovery should include update-splash dismissal commands.");
    Require(commands.Any(command => command.Category == "Extension packs" && command.Phrase == "close import splash" && command.Examples?.Contains("dismiss import splash") == true && command.Examples.Contains("cancel import splash")), "Command discovery should include import-splash dismissal commands.");
    Require(commands.Any(command => command.Category == "Updates" && command.Phrase == "read update summary again" && command.Examples?.Contains("repeat update summary") == true && command.Examples.Contains("read update notes again")), "Command discovery should include the update-summary replay command.");
    Require(commands.Any(command => command.Category == "Extension packs" && command.Phrase == "read import summary again" && command.Examples?.Contains("repeat import summary") == true && command.Examples.Contains("read pack import summary again")), "Command discovery should include the import-summary replay command.");
    Require(commands.Any(command => command.Category == "Navigation" && command.Phrase == "open release proof" && command.Examples?.Contains("show release proof") == true), "Command discovery should include release-proof walkthrough commands.");
    Require(commands.Any(command => command.Category == "Updates" && command.Phrase == "open release evidence" && command.Examples?.Contains("show release evidence") == true && command.Examples.Contains("open evidence")), "Command discovery should include the release evidence folder command.");
    Require(commands.Any(command => command.Category == "Updates" && command.Phrase == "open proof notes" && command.Examples?.Contains("show proof notes") == true), "Command discovery should include the proof notes folder command.");
    Require(commands.Any(command => command.Category == "Updates" && command.Phrase == "read proof notes" && command.Examples?.Contains("what proof notes exist") == true), "Command discovery should include the proof notes status readback command.");
    Require(commands.Any(command => command.Category == "Updates" && command.Phrase == "read evidence header" && command.Examples?.Contains("what header is missing") == true), "Command discovery should include the manual evidence header readback command.");
    Require(commands.Any(command => command.Category == "Updates" && command.Phrase == "create all proof notes" && command.RiskTier == CallsignCommandRiskTier.LocalStateChange && command.Examples?.Contains("prepare all proof notes") == true), "Command discovery should include the all-proof-notes preparation command.");
    Require(commands.Any(command => command.Category == "Updates" && command.Phrase == "create evidence draft" && command.RiskTier == CallsignCommandRiskTier.LocalStateChange && command.Examples?.Contains("prefill manual evidence") == true), "Command discovery should include the manual evidence draft creation command.");
    Require(commands.Any(command => command.Category == "Updates" && command.Phrase == "open evidence draft" && command.RiskTier == CallsignCommandRiskTier.LocalStateChange && command.Examples?.Contains("open manual evidence draft") == true), "Command discovery should include the manual evidence draft open command.");
    Require(commands.Any(command => command.Category == "Updates" && command.Phrase == "read evidence draft" && command.Examples?.Contains("what remains in the evidence draft") == true), "Command discovery should include the manual evidence draft readback command.");
    Require(commands.Any(command => command.Category == "Updates" && command.Phrase == "open manual evidence" && command.Examples?.Contains("open manual evidence template") == true), "Command discovery should include the manual evidence template command.");
    Require(commands.Any(command => command.Category == "Updates" && command.Phrase == "open manual evidence checklist" && command.Examples?.Contains("open checklist") == true && command.Examples.Contains("manual evidence checklist")), "Command discovery should include the manual evidence checklist command.");
    Require(commands.Any(command => command.Category == "Updates" && command.Phrase == "open installer" && !command.Examples.Contains("open release proof")), "Command discovery should keep installer-open and release-proof phrasing separate.");
    Require(commands.Any(command => command.Phrase == "show numbers"), "Command discovery should include visible control numbers.");
    Require(commands.Any(command => command.Category == "Visible controls" && command.Phrase == "show numbers" && command.Examples?.Contains("double click 1") == true && command.Examples.Contains("triple click 1") && command.Examples.Contains("right click save")), "Command discovery should include visible-control double-click, triple-click, and right-click commands.");
    Require(commands.Any(command => command.Category == "Visible controls" && command.Phrase == "show numbers" && command.Examples?.Contains("click number one") == true && command.Examples.Contains("choose item twenty one")), "Command discovery should include natural numbered visible-control phrases.");
    Require(commands.Any(command => command.Category == "Visible controls" && command.Phrase == "show numbers" && command.Examples?.Contains("double click control twelve") == true && command.Examples.Contains("right click option third")), "Command discovery should include natural numbered mouse-action phrases.");
    Require(commands.Any(command => command.Category == "Visible controls" && command.Phrase == "show numbers" && command.Examples?.Contains("focus username field") == true && command.Examples.Contains("go to address field") && command.Examples.Contains("go to field subject")), "Command discovery should include Voice Access-style field focus aliases.");
    Require(commands.Any(command => command.Category == "Visible controls" && command.Phrase == "show numbers" && command.Examples?.Contains("toggle number one") == true && command.Examples.Contains("toggle wifi") && command.Examples.Contains("flip dark mode") && command.Examples.Contains("expand settings") && command.Examples.Contains("open dropdown font") && command.Examples.Contains("close menu account")), "Command discovery should include visible-control toggle and expand/collapse aliases.");
    Require(commands.Any(command => command.Category == "Visible controls" && command.Phrase == "show numbers" && command.Examples?.Contains("move slider right two times") == true && command.Examples.Contains("move volume slider up 3 times") && command.Examples.Contains("adjust slider down one step")), "Command discovery should include visible slider movement aliases.");
    Require(commands.Any(command => command.Category == "Visible controls" && command.Phrase == "show numbers" && command.Examples?.Contains("cancel control numbers") == true), "Command discovery should include visible-control cancel commands.");
    Require(commands.Any(command => command.Phrase == "show grid"), "Command discovery should include mouse grid commands.");
    Require(commands.Any(command => command.Category == "Mouse grid" && command.Phrase == "show grid" && command.Examples?.Contains("show mouse grid") == true), "Command discovery should include mouse grid aliases.");
    Require(commands.Any(command => command.Category == "Mouse grid" && command.Phrase == "show grid" && command.Examples?.Contains("mouse grid") == true), "Command discovery should include mouse grid shorthand.");
    Require(commands.Any(command => command.Category == "Mouse grid" && command.Phrase == "show grid" && command.Examples?.Contains("open grid") == true), "Command discovery should include mouse grid open aliases.");
    Require(commands.Any(command => command.Category == "Mouse grid" && command.Phrase == "show grid" && command.Examples?.Contains("hide mouse grid") == true), "Command discovery should include mouse grid hide aliases.");
    Require(commands.Any(command => command.Category == "Mouse grid" && command.Phrase == "show grid" && command.Examples?.Contains("cancel mouse grid") == true), "Command discovery should include mouse grid cancel aliases.");
    Require(commands.Any(command => command.Category == "Mouse grid" && command.Phrase == "show grid" && command.Examples?.Contains("show mousegrid") == true), "Command discovery should include mousegrid compatibility aliases.");
    Require(commands.Any(command => command.Category == "Mouse grid" && command.Phrase == "show grid" && command.Examples?.Contains("show numbered grid") == true), "Command discovery should include numbered-grid aliases.");
    Require(commands.Any(command => command.Category == "Mouse grid" && command.Phrase == "show grid" && command.Examples?.Contains("grid five") == true && command.Examples.Contains("select cell third") && command.Examples.Contains("select square third")), "Command discovery should include natural mouse-grid cell selection phrases.");
    Require(commands.Any(command => command.Category == "Mouse grid" && command.Phrase == "show grid" && command.Examples?.Contains("click cell one") == true && command.Examples.Contains("click square one") && command.Examples.Contains("drag from cell one to cell ninth") && command.Examples.Contains("drag from square one to square ninth")), "Command discovery should include natural mouse-grid click and drag phrases.");
    Require(commands.Any(command => command.Category == "Keyboard" && command.Phrase == "show keyboard" && command.Examples?.Contains("show on screen keyboard") == true), "Command discovery should include on-screen keyboard aliases.");
    Require(commands.Any(command => command.Category == "Keyboard" && command.Phrase == "show keyboard" && command.Examples?.Contains("hide keyboard") == true), "Command discovery should include keyboard hide aliases.");
    Require(commands.Any(command => command.Category == "Keyboard" && command.Phrase == "show keyboard" && command.Examples?.Contains("cancel keyboard") == true), "Command discovery should include keyboard cancel aliases.");
    Require(commands.Any(command => command.Category == "Mouse" && command.Phrase == "click" && command.Examples?.Contains("double click") == true), "Command discovery should include mouse click aliases.");
    Require(commands.Any(command => command.Category == "Mouse" && command.Phrase == "click" && command.Examples?.Contains("tap") == true), "Command discovery should include tap as a mouse click alias.");
    Require(commands.Any(command => command.Category == "Mouse" && command.Phrase == "click" && command.Examples?.Contains("triple click") == true), "Command discovery should include mouse triple-click aliases.");
    Require(commands.Any(command => command.Category == "Mouse" && command.Phrase == "click" && command.Examples?.Contains("right click") == true), "Command discovery should include mouse right-click aliases.");
    Require(commands.Any(command => command.Category == "Mouse" && command.Phrase == "hold mouse" && command.Examples?.Contains("press and hold mouse button") == true), "Command discovery should include press-and-hold mouse button aliases.");
    Require(commands.Any(command => command.Category == "Mouse" && command.Phrase == "hold mouse" && command.Examples?.Contains("click and hold mouse button") == true && command.Examples.Contains("hold down left mouse button")), "Command discovery should include click-and-hold mouse button aliases.");
    Require(commands.Any(command => command.Category == "Mouse" && command.Phrase == "hold mouse" && command.Examples?.Contains("hold left mouse button") == true && command.Examples.Contains("release left mouse button")), "Command discovery should include left mouse hold/release aliases.");
    Require(commands.Any(command => command.Category == "Mouse" && command.Phrase == "hold mouse" && command.Examples?.Contains("let go of mouse button") == true), "Command discovery should include let-go mouse button aliases.");
    Require(commands.Any(command => command.Category == "Mouse" && command.Phrase == "mouse scroll up" && command.Examples?.Contains("scroll left") == true), "Command discovery should include mouse scroll aliases.");
    Require(commands.Any(command => command.Category == "Mouse" && command.Phrase == "mouse scroll up" && command.Examples?.Contains("mouse scroll down a little") == true), "Command discovery should include bounded mouse scroll aliases.");
    Require(commands.Any(command => command.Category == "Mouse" && command.Phrase == "mouse scroll up" && command.Examples?.Contains("scroll to top") == true && command.Examples.Contains("scroll to right edge")), "Command discovery should include foreground scroll-edge aliases.");
    Require(commands.Any(command => command.Category == "Mouse" && command.Phrase == "move mouse up" && command.Examples?.Contains("move mouse right") == true), "Command discovery should include mouse nudge aliases.");
    Require(commands.Any(command => command.Category == "Mouse" && command.Phrase == "move mouse up" && command.Examples?.Contains("move mouse top left") == true), "Command discovery should include diagonal continuous mouse movement examples.");
