    Require(commands.Any(command => command.Category == "File search" && command.Phrase == "search my files for budget" && command.Examples?.Contains("search my folders for invoices") == true && command.Examples.Contains("look in folders for receipts")), "Command discovery should include folder search aliases.");
    Require(commands.Any(command => command.Category == "File search" && command.Phrase == "search my files for budget" && command.Examples?.Contains("select first result") == true), "Command discovery should include numbered result-selection aliases.");
    Require(commands.Any(command => command.Category == "File search" && command.Phrase == "search my files for budget" && command.Examples?.Contains("open second result") == true), "Command discovery should include ordinal open-result aliases.");
    Require(commands.Any(command => command.Category == "File search" && command.Phrase == "search my files for budget" && command.Examples?.Contains("reveal file result 1") == true), "Command discovery should include reveal-result aliases.");
    Require(commands.Any(command => command.Category == "File search" && command.Phrase == "search my files for budget" && command.Examples?.Contains("show result folder 2") == true), "Command discovery should include folder-reveal aliases.");
    Require(commands.Any(command => command.Category == "File results" && command.Phrase == "open file result 1" && command.Examples?.Contains("open folder result 2") == true), "Command discovery should include folder-result open aliases.");
    Require(commands.Any(command => command.Category == "File results" && command.Phrase == "open file result 1" && command.Examples?.Contains("open containing folder for result 1") == true && command.Examples.Contains("show containing folder for result 2")), "Command discovery should include containing-folder result aliases.");
    Require(commands.Any(command => command.Category == "System" && command.Phrase == "close window" && command.Examples?.Contains("close active app") == true && command.Examples.Contains("press alt f4")), "Command discovery should keep close-window aliases on the approval-gated close command.");
    Require(commands.Any(command => command.Source.Contains("Open Core", StringComparison.OrdinalIgnoreCase) && command.Phrase == "Callsign"), "Command discovery should label the free core as the open-core source.");
    Require(commands.Any(command => command.Source.Contains("Community pack", StringComparison.OrdinalIgnoreCase) && command.Phrase == "sample pack echo"), "Command discovery should include community extension pack commands.");
    Require(commands.Any(command => command.Source.Contains("Community pack", StringComparison.OrdinalIgnoreCase) && command.Source.Contains("Sample Pack", StringComparison.OrdinalIgnoreCase) && command.Source.Contains("Free", StringComparison.OrdinalIgnoreCase) && command.Source.Contains("Disabled", StringComparison.OrdinalIgnoreCase)), "Command discovery should include community extension pack tier and availability.");
    Require(commands.Any(command => command.Phrase == "show numbers" && command.VoicePhrases?.Contains("show control numbers") == true), "Command discovery should include visible control aliases.");
    Require(commands.Any(command => command.Phrase == "show numbers" && command.VoicePhrases?.Contains("show buttons") == true && command.VoicePhrases.Contains("show click targets")), "Command discovery should include natural clickable-target aliases.");
    Require(commands.Any(command => command.Source.Contains("Community pack", StringComparison.OrdinalIgnoreCase) && command.Phrase == "sample pack echo" && command.VoicePhrases?.Contains("sample pack say") == true), "Command discovery should include community extension pack aliases.");
    Require(commands.Any(command => command.Category == "Packs" && command.Phrase == "import extension pack" && command.VoicePhrases?.Contains("import extension pack") == true && command.VoicePhrases.Contains("import dll") == true && command.VoicePhrases.Contains("drop dll") == true), "Command discovery should include pack import commands and DLL aliases.");
    Require(commands.Any(command => command.Category == "Packs" && command.Phrase == "update extension pack" && command.VoicePhrases?.Contains("update extension pack") == true), "Command discovery should include pack update commands.");
    Require(commands.Any(command => command.Category == "Packs" && command.Phrase == "rollback extension pack" && command.VoicePhrases?.Contains("rollback extension pack") == true), "Command discovery should include pack rollback commands.");
    Require(commands.Any(command => command.Category == "Packs" && command.Phrase == "refresh packs" && command.VoicePhrases?.Contains("reload packs") == true), "Command discovery should include pack refresh commands.");

    var helpText = CommandDiscoveryService.BuildHelpText(registry);
    Require(helpText.Contains("Callsign command palette", StringComparison.OrdinalIgnoreCase), "Help text should identify the command palette.");
    Require(helpText.Contains("Try getting started, open release proof, read release proof, read evidence status, read evidence header, read release blockers, read next proof, read proof steps, create proof note, create all proof notes, create evidence draft, open evidence draft, read evidence draft, read proof notes, open proof notes, read release gates, read visual status, open installer, read updates status, read voice mode status, read check-in status, read restart proof, read import summary again, read watch status, read paywall status, or open release evidence, open manual evidence, or open manual evidence checklist, open checklist, to reopen the setup walkthrough.", StringComparison.OrdinalIgnoreCase), "Help text should surface the getting-started, release-proof, release-proof readback, evidence-status, evidence-header, release-blocker, next-proof, proof-steps, proof-note, all-proof-notes, evidence-draft, evidence-draft-open, evidence-draft-readback, proof-notes-readback, proof-notes-folder, release-gates, visual-status, installer-open, voice-mode readback, check-in, restart-proof, import-replay, watch-status, paywall-status, release-evidence, manual-evidence, and checklist walkthrough routes.");
