static void CommandPaletteFiltersCommandsWithStatus()
{
    var repoRoot = FindRepositoryRoot();
    var commandPalettePath = Path.Combine(repoRoot, "src", "Callsign.UI", "CommandPaletteForm.cs");
    Require(File.Exists(commandPalettePath), $"Could not find command palette source at {commandPalettePath}.");
    var source = File.ReadAllText(commandPalettePath);
    Require(source.Contains("open checklist", StringComparison.OrdinalIgnoreCase), "Command palette source should mention the checklist route.");
    Require(source.Contains("open manual evidence checklist", StringComparison.OrdinalIgnoreCase), "Command palette source should mention the manual evidence checklist route.");
    Require(source.Contains("including feature-only review splashes", StringComparison.OrdinalIgnoreCase), "Command palette source should mention feature-only review splashes in the Updates quick filter.");
    Require(source.Contains("feature-only update splashes still appear when releases only add capabilities", StringComparison.OrdinalIgnoreCase), "Command palette source should mention feature-only update splashes in the voice cue.");

    var registry = PackTestSupport.CreateRegistry();
    registry.ImportPack(typeof(SampleCommandPack).Assembly.Location);
    registry.RegisterPack(new PaidSampleCommandPack());
    registry.RegisterPack(new FreshIdentityCommandPack());
    registry.RegisterPack(new ExternalSideEffectCommandPack());
    registry.RegisterPack(new BlockedCommandPack());
    var commands = CommandDiscoveryService.GetCommands(registry);

    using var owner = new Form();
    using var palette = new CommandPaletteForm();
    palette.ShowPalette(owner, commands);
    Require(palette.ContractText.Contains("search commands -> review availability -> choose a visible action", StringComparison.OrdinalIgnoreCase), $"Expected command palette contract guidance, got '{palette.ContractText}'.");
    using var filteredPalette = new CommandPaletteForm();
    filteredPalette.ShowPalette(owner, commands, "category:System");
    Require(string.Equals(filteredPalette.SearchText, "category:System", StringComparison.OrdinalIgnoreCase), $"Expected initial command palette filter to be applied, got '{filteredPalette.SearchText}'.");
    Require(filteredPalette.VisibleCommandCount > 0, "Prefiltered palette should still show system commands.");
    Require(filteredPalette.VoiceCueText.Contains("category:System", StringComparison.OrdinalIgnoreCase), $"Expected filtered palette voice cue to reflect the current filter, got '{filteredPalette.VoiceCueText}'.");
    using var plansFilteredPalette = new CommandPaletteForm();
    plansFilteredPalette.ShowPalette(owner, commands, "read plans status");
    Require(string.Equals(plansFilteredPalette.SearchText, "read plans status", StringComparison.OrdinalIgnoreCase), $"Expected the plans-status filter to be applied, got '{plansFilteredPalette.SearchText}'.");
    Require(plansFilteredPalette.VisibleCommandCount > 0, "Plans-status palette should still show matching commands.");
    Require(string.Equals(plansFilteredPalette.ActiveQuickFilterText, "Read Plans Status", StringComparison.OrdinalIgnoreCase), $"Expected the Read Plans Status chip to be highlighted, got '{plansFilteredPalette.ActiveQuickFilterText}'.");
    using var paywallFilteredPalette = new CommandPaletteForm();
    paywallFilteredPalette.ShowPalette(owner, commands, "paywall");
    Require(string.Equals(paywallFilteredPalette.SearchText, "paywall", StringComparison.OrdinalIgnoreCase), $"Expected the paywall filter to be applied, got '{paywallFilteredPalette.SearchText}'.");
    Require(paywallFilteredPalette.VisibleCommandCount > 0, "Paywall palette should still show matching commands.");
    Require(paywallFilteredPalette.VisibleCommandPhrases.Contains("open plans", StringComparison.OrdinalIgnoreCase), $"Expected paywall filtering to surface the Plans navigation command, got '{paywallFilteredPalette.VisibleCommandPhrases}'.");
    Require(paywallFilteredPalette.VisibleCommandPhrases.Contains("read paywall status", StringComparison.OrdinalIgnoreCase), $"Expected paywall filtering to surface the paywall-status command, got '{paywallFilteredPalette.VisibleCommandPhrases}'.");
    Require(palette.VisibleCommandCount == commands.Count, $"Expected all commands to be visible, got {palette.VisibleCommandCount} of {commands.Count}.");
    Require(palette.VisibleCategoryCount > 1, $"Expected grouped categories in the palette, got {palette.VisibleCategoryCount}.");
    Require(palette.ResultSummaryText.Contains("available", StringComparison.OrdinalIgnoreCase), $"Expected available-count status, got '{palette.ResultSummaryText}'.");
    Require(palette.ScopeSummaryText.Contains("Scope:", StringComparison.OrdinalIgnoreCase), $"Expected palette scope summary, got '{palette.ScopeSummaryText}'.");
    Require(palette.ScopeSummaryText.Contains("Free", StringComparison.OrdinalIgnoreCase), $"Expected palette scope summary to mention Free counts, got '{palette.ScopeSummaryText}'.");
    Require(palette.ScopeSummaryText.Contains("Pro", StringComparison.OrdinalIgnoreCase), $"Expected palette scope summary to mention Pro counts, got '{palette.ScopeSummaryText}'.");
    Require(palette.ScopeSummaryText.Contains("Advanced", StringComparison.OrdinalIgnoreCase), $"Expected palette scope summary to mention Advanced counts, got '{palette.ScopeSummaryText}'.");
    Require(palette.StatusStripAccessibleName.Contains("command palette status strip", StringComparison.OrdinalIgnoreCase), $"Expected palette status strip accessibility metadata, got '{palette.StatusStripAccessibleName}'.");
    Require(palette.StatusStripTexts.Contains("Browser: helpers visible", StringComparison.OrdinalIgnoreCase), $"Expected palette status strip to visibly include browser helper discovery, got '{palette.StatusStripTexts}'.");
    Require(palette.StatusScopeBadgeText.Contains("Scope:", StringComparison.OrdinalIgnoreCase), $"Expected palette scope badge text, got '{palette.StatusScopeBadgeText}'.");
    Require(palette.StatusResultBadgeText.Contains("Results:", StringComparison.OrdinalIgnoreCase), $"Expected palette result badge text, got '{palette.StatusResultBadgeText}'.");
    Require(palette.StatusSafetyBadgeText.Contains("Safety:", StringComparison.OrdinalIgnoreCase), $"Expected palette safety badge text, got '{palette.StatusSafetyBadgeText}'.");
    Require(palette.StatusSelectedBadgeText.Contains("Selected:", StringComparison.OrdinalIgnoreCase), $"Expected palette selected badge text, got '{palette.StatusSelectedBadgeText}'.");
    Require(palette.StatusPreviewBadgeText.Contains("Preview:", StringComparison.OrdinalIgnoreCase), $"Expected palette preview badge text, got '{palette.StatusPreviewBadgeText}'.");
    Require(palette.StatusSourceBadgeText.Contains("Source:", StringComparison.OrdinalIgnoreCase), $"Expected palette source badge text, got '{palette.StatusSourceBadgeText}'.");
    Require(palette.StatusAvailabilityBadgeText.Contains("Availability:", StringComparison.OrdinalIgnoreCase), $"Expected palette availability badge text, got '{palette.StatusAvailabilityBadgeText}'.");
    Require(palette.StatusBrowserBadgeText.Contains("Browser:", StringComparison.OrdinalIgnoreCase), $"Expected palette browser badge text, got '{palette.StatusBrowserBadgeText}'.");
    Require(palette.StatusBoundaryBadgeText.Contains("Boundary:", StringComparison.OrdinalIgnoreCase), $"Expected palette boundary badge text, got '{palette.StatusBoundaryBadgeText}'.");
    Require(palette.DetailsText.Contains("Boundary:", StringComparison.OrdinalIgnoreCase), $"Expected palette details to expose the selected command boundary, got '{palette.DetailsText}'.");
    Require(palette.CapabilityStripAccessibleName.Contains("capability strip", StringComparison.OrdinalIgnoreCase), $"Expected palette capability-strip accessibility metadata, got '{palette.CapabilityStripAccessibleName}'.");
    Require(palette.CapabilityFreeBadgeText.Contains("Free: Voice Access parity open core", StringComparison.OrdinalIgnoreCase), $"Expected palette capability strip to spell out the Free Voice Access parity boundary, got '{palette.CapabilityFreeBadgeText}'.");
    Require(palette.CapabilityProBadgeText.Contains("Pro: beyond-parity OS + browser + workflow", StringComparison.OrdinalIgnoreCase), $"Expected palette capability strip to spell out the Pro beyond-parity capability set, got '{palette.CapabilityProBadgeText}'.");
    Require(palette.CapabilityAdvancedBadgeText.Contains("Advanced: beyond-parity recipes + diagnostics + admin", StringComparison.OrdinalIgnoreCase), $"Expected palette capability strip to spell out the Advanced beyond-parity capability set, got '{palette.CapabilityAdvancedBadgeText}'.");
    RequireVisualContract(palette.VisualStyleName, "command palette");
    Require(palette.SurfaceAccessibleName.Contains("command palette", StringComparison.OrdinalIgnoreCase), $"Expected palette surface accessibility metadata, got '{palette.SurfaceAccessibleName}'.");
    Require(palette.SurfaceAccessibleDescription.Contains("tier", StringComparison.OrdinalIgnoreCase), $"Expected palette surface accessibility description to include tier context, got '{palette.SurfaceAccessibleDescription}'.");
    Require(palette.SurfaceAccessibleDescription.Contains("availability", StringComparison.OrdinalIgnoreCase), $"Expected palette surface accessibility description to include availability, got '{palette.SurfaceAccessibleDescription}'.");
    Require(palette.SurfaceAccessibleDescription.Contains("risk", StringComparison.OrdinalIgnoreCase), $"Expected palette surface accessibility description to include risk context, got '{palette.SurfaceAccessibleDescription}'.");
    Require(palette.TitleAccessibleName.Contains("Command palette", StringComparison.OrdinalIgnoreCase), $"Expected palette title accessibility metadata, got '{palette.TitleAccessibleName}'.");
    Require(palette.StatusStopBadgeText.Contains("STOP", StringComparison.OrdinalIgnoreCase), $"Expected palette status strip to expose a stop badge, got '{palette.StatusStopBadgeText}'.");
    Require(!string.IsNullOrWhiteSpace(palette.VoiceCueText), "Expected palette voice cue text to be present.");
    Require(palette.VoiceCueText.Contains("selected", StringComparison.OrdinalIgnoreCase) || palette.VoiceCueText.Contains("search commands, review availability, and choose a visible action", StringComparison.OrdinalIgnoreCase), $"Expected palette voice cue text to reflect either the current selection or the default discovery prompt, got '{palette.VoiceCueText}'.");
    Require(palette.VoiceCueText.Contains("open voice access guide", StringComparison.OrdinalIgnoreCase), $"Expected palette voice cue text to mention the Voice Access guide route, got '{palette.VoiceCueText}'.");
    Require(palette.VoiceCueText.Contains("feature-only update splashes", StringComparison.OrdinalIgnoreCase), $"Expected palette voice cue text to mention feature-only update splashes, got '{palette.VoiceCueText}'.");
    Require(palette.QuickFilterTexts.Contains("Open Release Evidence", StringComparison.OrdinalIgnoreCase), $"Expected palette quick filters to include the release evidence action, got '{palette.QuickFilterTexts}'.");
    Require(palette.QuickFilterTexts.Contains("Open Checklist", StringComparison.OrdinalIgnoreCase), $"Expected palette quick filters to include the checklist action, got '{palette.QuickFilterTexts}'.");
    Require(palette.QuickFilterTexts.Contains("Open Manual Evidence", StringComparison.OrdinalIgnoreCase), $"Expected palette quick filters to include the manual evidence action, got '{palette.QuickFilterTexts}'.");
    Require(palette.QuickFilterTexts.Contains("Open Manual Evidence Checklist", StringComparison.OrdinalIgnoreCase), $"Expected palette quick filters to include the manual evidence checklist action, got '{palette.QuickFilterTexts}'.");
    Require(palette.QuickFilterTexts.Contains("Read Check-In Status", StringComparison.OrdinalIgnoreCase), $"Expected palette quick filters to include the check-in status action, got '{palette.QuickFilterTexts}'.");
    Require(palette.QuickFilterTexts.Contains("Read Plans Status", StringComparison.OrdinalIgnoreCase), $"Expected palette quick filters to include the plans status action, got '{palette.QuickFilterTexts}'.");
    Require(palette.QuickFilterTexts.Contains("Restart Listening", StringComparison.OrdinalIgnoreCase), $"Expected palette quick filters to include the restart-listening action, got '{palette.QuickFilterTexts}'.");
