    Require(palette.StatusSourceBadgeText.Contains($"extensions {commands.Count(command => !command.Source.StartsWith("Open Core", StringComparison.OrdinalIgnoreCase))}", StringComparison.OrdinalIgnoreCase), $"Expected palette source badge to count extension commands, got '{palette.StatusSourceBadgeText}'.");
