    palette.SetSearchText("Pro entitlement");
    Require(palette.VisibleCommandCount == 1, $"Expected Pro entitlement search to find the gated paid-pack result, got {palette.VisibleCommandCount}.");
    Require(palette.FirstVisibleAvailabilityText?.Contains("Pro entitlement required", StringComparison.OrdinalIgnoreCase) == true, $"Expected Pro entitlement search to show the entitlement gate, got '{palette.FirstVisibleAvailabilityText}'.");

    var disabledRegistry = PackTestSupport.CreateRegistry();
    disabledRegistry.ImportPack(typeof(SampleCommandPack).Assembly.Location);
    palette.ShowPalette(null!, CommandDiscoveryService.GetCommands(disabledRegistry));
    palette.SetSearchText("status:disabled");
    Require(palette.VisibleCommandCount == 1, $"Expected structured disabled-status filter to find the imported pack, got {palette.VisibleCommandCount}.");
    Require(palette.FirstVisibleAvailabilityText?.Contains("Disabled", StringComparison.OrdinalIgnoreCase) == true, $"Expected disabled-status filter to show the disabled gate, got '{palette.FirstVisibleAvailabilityText}'.");
    Require(palette.FirstVisibleAvailabilityText?.Contains("will not route", StringComparison.OrdinalIgnoreCase) == true, $"Expected disabled-status filter to say disabled commands will not route, got '{palette.FirstVisibleAvailabilityText}'.");
    Require(palette.DetailsText.Contains("until enabled from Packs", StringComparison.OrdinalIgnoreCase), $"Expected disabled command details to explain the enablement routing gate, got '{palette.DetailsText}'.");
    Require(palette.VoiceCueText.Contains("will not route", StringComparison.OrdinalIgnoreCase), $"Expected disabled command voice cue to say it will not route, got '{palette.VoiceCueText}'.");
    Require(string.Equals(palette.ActiveQuickFilterText, "Disabled", StringComparison.OrdinalIgnoreCase), $"Expected Disabled chip to be highlighted, got '{palette.ActiveQuickFilterText}'.");

    palette.SetSearchText("source:free");
    Require(palette.VisibleCommandCount > 0, "Expected open-core source filter to keep open-core commands visible.");
    Require(palette.VisibleCommandCount < commands.Count, "Expected open-core source filter to narrow the list.");

    palette.SetSearchText("source:open core");
    Require(palette.VisibleCommandCount > 0, "Expected open-core source filter to keep open-core commands visible.");
    Require(palette.VisibleCommandCount < commands.Count, "Expected open-core source filter to narrow the list.");

    palette.SetSearchText("category:system");
    Require(palette.VisibleCommandCount > 0, "Expected category:system filter to keep system commands visible.");
    Require(palette.DetailsText.Contains("System", StringComparison.OrdinalIgnoreCase), $"Expected system category filter to surface system details, got '{palette.DetailsText}'.");

    palette.SetSearchText("category:browser");
    Require(palette.VisibleCommandCount > 0, "Expected category:browser filter to keep browser commands visible.");
    Require(palette.DetailsText.Contains("Browser", StringComparison.OrdinalIgnoreCase), $"Expected browser category filter to surface browser details, got '{palette.DetailsText}'.");

    palette.SetSearchText("category:dictation");
    Require(palette.VisibleCommandCount > 0, "Expected category:dictation filter to keep dictation commands visible.");
    Require(palette.DetailsText.Contains("Dictation", StringComparison.OrdinalIgnoreCase), $"Expected dictation category filter to surface dictation details, got '{palette.DetailsText}'.");

    palette.ShowPalette(null!, gatedCommands);
    palette.SetSearchText("will not route");
    Require(palette.VisibleCommandCount == 1, $"Expected will-not-route search to find the gated paid-pack result, got {palette.VisibleCommandCount}.");
    Require(palette.DetailsText.Contains("will not route", StringComparison.OrdinalIgnoreCase), $"Expected will-not-route search to keep routing status visible, got '{palette.DetailsText}'.");
}

static void VerifiedSessionRoutesBuiltInParityFamilies()
{
    var repoRoot = FindRepositoryRoot();
    var uiPath = Path.Combine(repoRoot, "src", "Callsign.UI", "MainForm.cs");
    var serviceWorkerPath = Path.Combine(repoRoot, "src", "Callsign.Service", "CallsignRuntimeWorker.cs");
    var serviceProgramPath = Path.Combine(repoRoot, "src", "Callsign.Service", "Program.cs");
    var commandPalettePath = Path.Combine(repoRoot, "src", "Callsign.UI", "CommandPaletteForm.cs");
    var visibleControlsOverlayPath = Path.Combine(repoRoot, "src", "Callsign.UI", "VisibleControlsOverlayForm.cs");
    Require(File.Exists(uiPath), $"Could not find UI source at {uiPath}.");
    Require(File.Exists(serviceWorkerPath), $"Could not find service worker source at {serviceWorkerPath}.");
    Require(File.Exists(serviceProgramPath), $"Could not find service program source at {serviceProgramPath}.");
    Require(File.Exists(commandPalettePath), $"Could not find command palette source at {commandPalettePath}.");
    Require(File.Exists(visibleControlsOverlayPath), $"Could not find visible controls overlay source at {visibleControlsOverlayPath}.");
    using var form = new MainForm();

    var source = File.ReadAllText(uiPath);
    var serviceWorkerSource = File.ReadAllText(serviceWorkerPath);
    var serviceProgramSource = File.ReadAllText(serviceProgramPath);
    var commandPaletteSource = File.ReadAllText(commandPalettePath);
    var visibleControlsOverlaySource = File.ReadAllText(visibleControlsOverlayPath);
    var waitingForCommandStart = source.IndexOf("if (_session.State == AlphaSessionState.WaitingForCommand)", StringComparison.OrdinalIgnoreCase);
    Require(waitingForCommandStart >= 0, "Main form should have a verified command-session branch.");
    var waitingForCommandSource = source[waitingForCommandStart..];

    var systemIntentCheck = waitingForCommandSource.IndexOf("uiNavigationIntent.Kind == AlphaVoiceIntentKind.SystemControl", StringComparison.OrdinalIgnoreCase);
    var fileIntentCheck = waitingForCommandSource.IndexOf("uiNavigationIntent.Kind == AlphaVoiceIntentKind.FileSearch", StringComparison.OrdinalIgnoreCase);
    var dictationIntentCheck = waitingForCommandSource.IndexOf("uiNavigationIntent.Kind == AlphaVoiceIntentKind.Dictation", StringComparison.OrdinalIgnoreCase);
    var startMenuFallback = waitingForCommandSource.IndexOf("CaptureCommand();", StringComparison.OrdinalIgnoreCase);

    Require(systemIntentCheck >= 0, "Verified command branch should handle system-control intents.");
    Require(fileIntentCheck >= 0, "Verified command branch should handle file-search intents.");
    Require(dictationIntentCheck >= 0, "Verified command branch should handle dictation intents.");
    Require(startMenuFallback >= 0, "Verified command branch should still keep the Start menu launch fallback.");
    Require(systemIntentCheck < startMenuFallback, "System-control intents should execute before app-launch fallback.");
    Require(fileIntentCheck < startMenuFallback, "File-search intents should execute before app-launch fallback.");
    Require(dictationIntentCheck < startMenuFallback, "Dictation intents should execute before app-launch fallback.");

    Require(source.Contains("private bool TryAuthorizeBuiltInIntent(AlphaVoiceIntent intent", StringComparison.OrdinalIgnoreCase), "Built-in parity commands should share a policy authorization helper.");
    Require(source.Contains("CallsignCommandPolicy.Evaluate(definition, identityVerified, freshIdentity)", StringComparison.OrdinalIgnoreCase), "Built-in parity command authorization should use the policy engine.");
    Require(serviceWorkerSource.Contains("ExtensionCommandIdentityFreshness", StringComparison.OrdinalIgnoreCase), "Service-side extension commands should define a bounded identity freshness window.");
    Require(serviceWorkerSource.Contains("var identityVerified = string.Equals(_session.VerifiedCallsign, profile.Callsign", StringComparison.OrdinalIgnoreCase), "Service-side extension commands should derive identity verification from the active session and profile.");
    Require(serviceWorkerSource.Contains("var freshIdentityVerified = _session.HasFreshIdentity(ExtensionCommandIdentityFreshness)", StringComparison.OrdinalIgnoreCase), "Service-side extension commands should derive fresh identity proof from the session state machine.");
    Require(serviceWorkerSource.Contains("identityVerified: identityVerified", StringComparison.OrdinalIgnoreCase), "Service-side extension execution should pass the session-derived identity flag to the registry.");
    Require(serviceWorkerSource.Contains("freshIdentityVerified: freshIdentityVerified", StringComparison.OrdinalIgnoreCase), "Service-side extension execution should pass the session-derived fresh-identity flag to the registry.");
    Require(!serviceWorkerSource.Contains("identityVerified: true,\r\n            freshIdentityVerified: true", StringComparison.OrdinalIgnoreCase)
        && !serviceWorkerSource.Contains("identityVerified: true,\n            freshIdentityVerified: true", StringComparison.OrdinalIgnoreCase),
        "Service-side extension execution must not hard-code identity and fresh-identity proof.");
    Require(serviceProgramSource.Contains("AddSingleton<SystemControlService>", StringComparison.OrdinalIgnoreCase), "Service runtime should register the system-control adapter for background Voice Access parity commands.");
    Require(serviceWorkerSource.Contains("TryExecuteSystemControlCommand(intent, profile", StringComparison.OrdinalIgnoreCase), "Service verified command execution should route system-control intents before Start menu fallback.");
    Require(serviceWorkerSource.Contains("TryAuthorizeServiceBuiltInIntent", StringComparison.OrdinalIgnoreCase), "Service system-control execution should evaluate built-in command policy before visible execution.");
    Require(serviceWorkerSource.Contains("CallsignCommandPolicy.Evaluate(definition, identityVerified, freshIdentity)", StringComparison.OrdinalIgnoreCase), "Service built-in system commands should use the policy engine and session-derived identity.");
    Require(serviceWorkerSource.Contains("TryExecuteBrowserCommand(intent, profile", StringComparison.OrdinalIgnoreCase), "Service verified command execution should route browser intents with the active profile.");
    Require(serviceWorkerSource.Contains("IsBrowserActionTarget(intent.Target)", StringComparison.OrdinalIgnoreCase), "Service browser command routing should recognize every browser-* action target before URL/search fallback.");
    Require(serviceWorkerSource.Contains("_browserLaunchService.TryExecuteBrowserAction(intent.Target", StringComparison.OrdinalIgnoreCase), "Service browser command routing should forward browser-* actions through BrowserLaunchService.");
    Require(serviceWorkerSource.Contains("target.Trim().StartsWith(\"browser-\"", StringComparison.OrdinalIgnoreCase), "Service browser actions should not fall back to browser search when a browser-* action fails.");
    foreach (var browserAction in new[]
             {
                 "browser-private-window",
                 "browser-save-page",
                 "browser-print-page",
                 "browser-duplicate-tab",
                 "browser-copy-address",
                 "browser-home",
                 "browser-fullscreen",
                 "browser-open-downloads",
                 "browser-open-history",
                 "browser-find-text:",
                 "browser-address-text:",
                 "browser-select-tab:",
                 "browser-scroll-down-pages:",
                 "browser-zoom-reset"
             })
    {
        Require(BrowserLaunchServiceCanExecute(browserAction), $"BrowserLaunchService should expose action support for {browserAction}.");
    }
    Require(serviceWorkerSource.Contains("TryExecuteFileSearchCommand(intent, profile", StringComparison.OrdinalIgnoreCase), "Service verified command execution should route file-search intents with the active profile.");
    Require(serviceWorkerSource.Contains("TryExecuteDictationCommand(intent, profile", StringComparison.OrdinalIgnoreCase), "Service verified command execution should route dictation intents with the active profile.");
    Require(serviceWorkerSource.Contains("AlphaVoiceIntentKind.Browser => CallsignCommandKind.Browser", StringComparison.OrdinalIgnoreCase), "Service built-in policy definitions should cover browser commands.");
    Require(serviceWorkerSource.Contains("AlphaVoiceIntentKind.FileSearch => CallsignCommandKind.FileSearch", StringComparison.OrdinalIgnoreCase), "Service built-in policy definitions should cover file-search commands.");
    Require(serviceWorkerSource.Contains("AlphaVoiceIntentKind.Dictation => CallsignCommandKind.Dictation", StringComparison.OrdinalIgnoreCase), "Service built-in policy definitions should cover dictation commands.");
    Require(serviceWorkerSource.Contains("AlphaVoiceIntentKind.Dictation => CallsignCommandApprovalRequirement.RequireFreshIdentity", StringComparison.OrdinalIgnoreCase), "Service dictation commands should require fresh identity through built-in policy.");
    Require(serviceWorkerSource.Contains("RequestUiMode(\"Browser\")", StringComparison.OrdinalIgnoreCase), "Service browser commands should request the visible Browser surface.");
    Require(serviceWorkerSource.Contains("RequestUiMode(\"Files\")", StringComparison.OrdinalIgnoreCase), "Service file-search commands should request the visible Files surface.");
    Require(serviceWorkerSource.Contains("RequestUiMode(\"Dictation\")", StringComparison.OrdinalIgnoreCase), "Service dictation commands should request the visible Dictation surface.");
    Require(source.Contains("blocked_external_side_effect", StringComparison.OrdinalIgnoreCase), "Main form should audit blocked external side-effect voice commands.");
    Require(source.Contains("will not submit, send, upload, post, pay, accept terms, or run downloaded software", StringComparison.OrdinalIgnoreCase), "Main form should visibly explain blocked submit/send/upload/pay commands.");
    Require(serviceWorkerSource.Contains("ui-blocked-external-side-effect", StringComparison.OrdinalIgnoreCase), "Service runtime should route blocked external side-effect requests to the visible UI.");
    Require(serviceWorkerSource.Contains("will not submit, send, upload, post, pay, accept terms, or run downloaded software", StringComparison.OrdinalIgnoreCase), "Service runtime should surface blocked submit/send/upload/pay commands visibly.");
    Require(serviceWorkerSource.Contains("private readonly AlphaAuditLog _auditLog", StringComparison.OrdinalIgnoreCase), "Service runtime should own a structured alpha audit writer.");
    Require(serviceWorkerSource.Contains("_auditLog = new AlphaAuditLog(profileStore)", StringComparison.OrdinalIgnoreCase), "Service runtime should initialize the audit writer from the profile store.");
    Require(serviceWorkerSource.Contains("alpha.service_command_execution", StringComparison.OrdinalIgnoreCase), "Service runtime should write service-command execution audit events.");
    Require(serviceWorkerSource.Contains("auditSource: \"service_runtime\"", StringComparison.OrdinalIgnoreCase), "Service runtime audit records should be marked as service-runtime events.");
    Require(serviceWorkerSource.Contains("verificationMethod: \"visible_status\"", StringComparison.OrdinalIgnoreCase), "Service runtime audit records should include visible-status verification metadata.");
    Require(serviceWorkerSource.Contains("Audit warning:", StringComparison.OrdinalIgnoreCase), "Service runtime should make audit-write failures visible in status/action history.");
    Require(serviceWorkerSource.Contains("Service audit logging failed; review profile storage and disk permissions before trusting this action history", StringComparison.OrdinalIgnoreCase), "Service runtime should use bounded audit-failure guidance instead of suppressing audit errors.");
    Require(serviceWorkerSource.Contains("if (string.Equals(_statusMessage, message, StringComparison.Ordinal))", StringComparison.OrdinalIgnoreCase), "Service runtime should update the visible status when audit logging fails for a just-recorded action.");
    Require(serviceWorkerSource.Contains("RecordServiceAction(\"browser\", intent.Target, browserMessage, succeeded: browserSucceeded, profile)", StringComparison.OrdinalIgnoreCase), "Service browser commands should pass the active profile into audit-backed action recording.");
    Require(serviceWorkerSource.Contains("RecordServiceAction(\"file_search\", intent.Target, fileSearchMessage, succeeded: fileSearchSucceeded, profile)", StringComparison.OrdinalIgnoreCase), "Service file-search commands should pass the active profile into audit-backed action recording.");
    Require(serviceWorkerSource.Contains("RecordServiceAction(\"dictation\", \"service dictation\", dictationMessage, succeeded: dictationSucceeded, profile)", StringComparison.OrdinalIgnoreCase), "Service dictation commands should pass the active profile into audit-backed action recording.");
    Require(serviceWorkerSource.Contains("RecordServiceAction(\"system\", intent.Target, systemMessage, succeeded: systemSucceeded, profile)", StringComparison.OrdinalIgnoreCase), "Service system commands should pass the active profile into audit-backed action recording.");
    Require(serviceWorkerSource.Contains("command '{definition.DisplayName}' requires visible approval", StringComparison.OrdinalIgnoreCase)
        && serviceWorkerSource.Contains("requires visible approval in the visible Callsign surface before execution", StringComparison.OrdinalIgnoreCase),
        "Service approval-required system commands should fail closed and request visible System-tab approval.");
    Require(serviceWorkerSource.Contains("_systemControlService.TryExecute(action", StringComparison.OrdinalIgnoreCase), "Service should execute safe system-control actions through SystemControlService.");
    Require(serviceWorkerSource.Contains("_systemControlService.ResolveVisibleWindow", StringComparison.OrdinalIgnoreCase), "Service should resolve named visible-window switching through SystemControlService.");
    Require(serviceWorkerSource.Contains("Open the System tab to choose the visible numbered window", StringComparison.OrdinalIgnoreCase), "Service should defer ambiguous window switching to visible numbered choices.");
    Require(source.Contains("AuditBuiltInPolicyDecision(intent, \"allowed\"", StringComparison.OrdinalIgnoreCase), "Built-in parity commands should audit allowed policy decisions.");
    Require(source.Contains("verificationMethod: \"policy_evaluation\"", StringComparison.OrdinalIgnoreCase), "Built-in policy audit records should include policy-evaluation verification metadata.");
    Require(source.Contains("Built-in command passed Callsign policy evaluation", StringComparison.OrdinalIgnoreCase), "Built-in policy audit records should summarize allowed policy verification.");
    Require(source.Contains("Built-in command was blocked by Callsign policy evaluation", StringComparison.OrdinalIgnoreCase), "Built-in policy audit records should summarize blocked policy verification.");
    Require(source.Contains("AccessibleName = \"Account save\"", StringComparison.OrdinalIgnoreCase), "Account save button should expose a spoken-label accessible name.");
    Require(source.Contains("AccessibleName = \"Account train voice identity\"", StringComparison.OrdinalIgnoreCase), "Account voice-training button should expose a spoken-label accessible name.");
    Require(source.Contains("AccessibleName = \"Voice record sample\"", StringComparison.OrdinalIgnoreCase), "Voice record button should expose a spoken-label accessible name.");
    Require(source.Contains("AccessibleName = \"Voice reset\"", StringComparison.OrdinalIgnoreCase), "Voice reset button should expose a spoken-label accessible name.");
    Require(source.Contains("AccessibleName = \"Session start listening\"", StringComparison.OrdinalIgnoreCase), "Session start-listening button should expose a spoken-label accessible name.");
    Require(source.Contains("AccessibleName = \"Session restart listening\"", StringComparison.OrdinalIgnoreCase), "Session restart-listening button should expose a spoken-label accessible name.");
    Require(source.Contains("voice access wake up, wake up, unmute microphone", StringComparison.OrdinalIgnoreCase), "Session start-listening button should expose Voice Access-style wake aliases.");
    Require(source.Contains("voice access sleep, go to sleep, turn off microphone, turn off voice access, stop voice access, close voice access, exit voice access, quit voice access, mute microphone", StringComparison.OrdinalIgnoreCase), "Session stop-listening button should expose Voice Access-style sleep and exit aliases.");
    Require(source.Contains("Voice phrases: restart listening, restart voice, restart callsign, restart microphone, restart voice access.", StringComparison.OrdinalIgnoreCase), "Session restart-listening button should expose restart aliases.");
    Require(source.Contains("AccessibleName = \"Session readiness\"", StringComparison.OrdinalIgnoreCase), "Session readiness label should expose a spoken-label accessible name.");
    Require(source.Contains("Readiness: create or select a profile.", StringComparison.OrdinalIgnoreCase), "Session readiness label should explain the default state.");
    Require(source.Contains("Next: say the app name.", StringComparison.OrdinalIgnoreCase), "Session next-action guidance should prompt for the app name.");
    Require(source.Contains("After identity, say the app name to launch.", StringComparison.OrdinalIgnoreCase), "Session hint details should prompt for the app name to launch.");
    Require(source.Contains("Say the app name before continuing.", StringComparison.OrdinalIgnoreCase), "Session command capture should prompt for the app name when the command text is blank.");
    var readinessMethod = typeof(MainForm).GetMethod("FormatSessionReadinessText", BindingFlags.NonPublic | BindingFlags.Static, [typeof(UserProfile), typeof(AlphaSessionState)]);
    Require(readinessMethod != null, "MainForm should keep the session readiness formatter available.");
    var enrolledProfile = new UserProfile
    {
        Callsign = "Echo One",
        Settings = new UserSettings
        {
            VoiceSamplesRecorded = 3,
            VoiceSamplesRequired = 3,
            VoiceEnrolledUtc = DateTime.UtcNow
        }
    };
    var idleReady = (string?)readinessMethod!.Invoke(null, [enrolledProfile, AlphaSessionState.Idle]) ?? string.Empty;
    Require(idleReady.Contains("Echo One is enrolled", StringComparison.OrdinalIgnoreCase), $"Expected idle readiness to reflect an enrolled profile, got '{idleReady}'.");
    Require(idleReady.Contains("Say Callsign to wake", StringComparison.OrdinalIgnoreCase), $"Expected idle readiness to prompt for wake, got '{idleReady}'.");
    var identityReady = (string?)readinessMethod.Invoke(null, [enrolledProfile, AlphaSessionState.WaitingForIdentity]) ?? string.Empty;
    Require(identityReady.Contains("ready for identity confirmation", StringComparison.OrdinalIgnoreCase), $"Expected identity readiness to mention confirmation, got '{identityReady}'.");
    var commandReady = (string?)readinessMethod.Invoke(null, [enrolledProfile, AlphaSessionState.WaitingForCommand]) ?? string.Empty;
    Require(commandReady.Contains("Say the app name or a visible command", StringComparison.OrdinalIgnoreCase), $"Expected command readiness to mention visible command capture, got '{commandReady}'.");
    Require(source.Contains("The session needs identity before it accepts a command.", StringComparison.OrdinalIgnoreCase), "Session flow should explain the identity gate in the command branch.");
    var sessionReadinessProperty = typeof(MainForm).GetProperty("SessionReadinessBadgeText", BindingFlags.Instance | BindingFlags.Public);
    Require(sessionReadinessProperty != null, "MainForm should expose the session readiness badge text.");
    using var readinessForm = new MainForm();
    var sessionReadinessText = sessionReadinessProperty!.GetValue(readinessForm) as string ?? string.Empty;
    Require(sessionReadinessText.Contains("Ready:", StringComparison.OrdinalIgnoreCase), $"Expected session readiness badge text to remain state-aware, got '{sessionReadinessText}'.");
    Require(
        sessionReadinessText.Contains("profile needed", StringComparison.OrdinalIgnoreCase)
        || sessionReadinessText.Contains("fresh sample", StringComparison.OrdinalIgnoreCase)
        || sessionReadinessText.Contains("is enrolled", StringComparison.OrdinalIgnoreCase),
        $"Expected session readiness badge text to reflect the current profile and enrollment state, got '{sessionReadinessText}'.");
    Require(source.Contains("AccessibleName = \"Voice mode commands only\"", StringComparison.OrdinalIgnoreCase), "Voice mode commands-only control should expose a spoken-label accessible name.");
    Require(source.Contains("AccessibleName = \"Voice mode dictation only\"", StringComparison.OrdinalIgnoreCase), "Voice mode dictation-only control should expose a spoken-label accessible name.");
    Require(source.Contains("AccessibleName = \"Voice mode default\"", StringComparison.OrdinalIgnoreCase), "Voice mode default control should expose a spoken-label accessible name.");
    Require(source.Contains("Voice phrases: commands only mode, start command mode, turn off dictation mode.", StringComparison.OrdinalIgnoreCase), "Voice mode commands-only control should expose its spoken phrases.");
    Require(source.Contains("Voice phrases: default mode, commands and dictation mode, commands plus dictation mode.", StringComparison.OrdinalIgnoreCase), "Voice mode default control should expose its spoken phrases.");
    Require(source.Contains("AccessibleName = \"Voice contract\"", StringComparison.OrdinalIgnoreCase), "Voice contract strip should expose an accessible name.");
    Require(source.Contains("record sample -> review voice state -> activate account", StringComparison.OrdinalIgnoreCase), "Voice contract strip should summarize the voice enrollment flow.");
    Require(source.Contains("AccessibleName = \"Session verify callsign\"", StringComparison.OrdinalIgnoreCase), "Session verify button should expose a spoken-label accessible name.");
    Require(source.Contains("Voice phrases: confirm app, 1, click 1, choose result one.", StringComparison.OrdinalIgnoreCase), "Session confirm-app button should expose numbered app-choice phrases.");
    Require(source.Contains("Visible numbered app choices for ambiguous launch requests.", StringComparison.OrdinalIgnoreCase), "Session app-choice list should describe the visible numbered-choice mode.");
    Require(source.Contains("next app choice", StringComparison.OrdinalIgnoreCase) && source.Contains("previous app choice", StringComparison.OrdinalIgnoreCase), "Session app-choice flow should surface spoken next/previous navigation.");
    Require(source.Contains("AccessibleName = \"Session cancel\"", StringComparison.OrdinalIgnoreCase), "Session cancel button should expose a spoken-label accessible name.");
    Require(source.Contains("AccessibleName = \"Wake status strip\"", StringComparison.OrdinalIgnoreCase), "Session should expose a compact wake status strip.");
