    Require(source.Contains("AccessibleName = \"Session next action\"", StringComparison.OrdinalIgnoreCase), "Session next-action badge should expose a spoken-label accessible name.");
    Require(source.Contains("CreateSessionBadge(\"Next: say Callsign.\"", StringComparison.OrdinalIgnoreCase), "Session should expose a next-action badge.");
    Require(source.Contains("UpdateWakeStatusStrip(", StringComparison.OrdinalIgnoreCase), "Session refresh should keep the wake status strip live.");
