    Require(source.Contains("file, script, settings, installer, and app schemes are blocked here", StringComparison.OrdinalIgnoreCase), "Browser safety line should explain blocked non-web schemes.");
    Require(source.Contains("do not inspect page contents or run hidden scripts", StringComparison.OrdinalIgnoreCase), "Browser safety line should explain no hidden page inspection or script execution.");
    Require(source.Contains("AccessibleName = \"Browser contract\"", StringComparison.OrdinalIgnoreCase), "Browser contract strip should expose an accessible name.");
    Require(source.Contains("open web target -> visible browser action -> review or stop", StringComparison.OrdinalIgnoreCase), "Browser contract strip should summarize the browser flow.");
    Require(source.Contains("AccessibleName = \"Browser show numbers\"", StringComparison.OrdinalIgnoreCase), "Browser show-numbers button should expose a spoken-label accessible name.");
    Require(source.Contains("AccessibleName = \"Browser show grid\"", StringComparison.OrdinalIgnoreCase), "Browser show-grid button should expose a spoken-label accessible name.");
    Require(source.Contains("AccessibleName = \"Browser hide overlays\"", StringComparison.OrdinalIgnoreCase), "Browser hide-overlays button should expose a spoken-label accessible name.");
