        && source.Contains("_browserVoiceCueLabel.Text.StartsWith(\"Voice cue:\", StringComparison.OrdinalIgnoreCase)", StringComparison.OrdinalIgnoreCase), "Browser refresh should keep the cue badge live.");
    Require(source.Contains("_browserActionBadge.Text = string.IsNullOrWhiteSpace(_browserLastActionLabel.Text)", StringComparison.OrdinalIgnoreCase), "Browser refresh should keep the action badge live.");
    Require(source.Contains("_browserSafetyBadge.Text = \"Safety: web only\"", StringComparison.OrdinalIgnoreCase), "Browser refresh should keep the safety badge live.");
