    Require(source.Contains("ExecuteSystemAction(intent.Target", StringComparison.OrdinalIgnoreCase), "System-control intents should execute through the visible system handler.");
    Require(source.Contains("ExecuteSystemShellSurfaceAction", StringComparison.OrdinalIgnoreCase), "System shell-surface buttons should execute through the visible policy-aware shell handler.");
    Require(source.Contains("SearchFiles();", StringComparison.OrdinalIgnoreCase), "File-search intents should execute through the visible file search handler.");
    Require(source.Contains("StartDictation();", StringComparison.OrdinalIgnoreCase), "Dictation intents should execute through the visible dictation review handler.");
}

static void PacksImportSummaryUpdatesAfterImport()
{
    var sourceAssembly = typeof(SampleCommandPack).Assembly.Location;
    var sourceDirectory = Path.Combine(Path.GetTempPath(), "Callsign.AlphaSmoke", "packs-import-summary", Guid.NewGuid().ToString("N"));
    Directory.CreateDirectory(sourceDirectory);

    try
    {
        var sourceCopy = Path.Combine(sourceDirectory, Path.GetFileName(sourceAssembly));
        File.Copy(sourceAssembly, sourceCopy, overwrite: true);

        using var form = new MainForm();
        var importMethod = typeof(MainForm).GetMethod("ImportCommunityPacks", BindingFlags.Instance | BindingFlags.NonPublic);
        Require(importMethod != null, "MainForm should expose the community pack import handler.");
        importMethod!.Invoke(form, new object[] { new[] { sourceCopy }, false });

        var packsImportSummaryProperty = typeof(MainForm).GetProperty("PacksImportSummaryText", BindingFlags.Instance | BindingFlags.Public);
        Require(packsImportSummaryProperty != null, "MainForm should expose the packs import summary text.");
        var summaryText = packsImportSummaryProperty!.GetValue(form) as string ?? string.Empty;
        Require(summaryText.Contains("Last import:", StringComparison.OrdinalIgnoreCase), $"Expected a visible last-import summary, got '{summaryText}'.");
        Require(summaryText.Contains("imported disabled for review", StringComparison.OrdinalIgnoreCase), $"Expected review-first import guidance, got '{summaryText}'.");
        Require(summaryText.Contains("Feature preview:", StringComparison.OrdinalIgnoreCase), $"Expected review-first import guidance to include a feature preview, got '{summaryText}'.");
        Require(summaryText.Contains("Sample Pack", StringComparison.OrdinalIgnoreCase) || summaryText.Contains("sample-echo", StringComparison.OrdinalIgnoreCase), $"Expected review-first import guidance to name the imported pack or command, got '{summaryText}'.");
    }
    finally
    {
        try
        {
            CallsignCommandRegistry.Shared.RemovePack("sample-pack", out _, deleteAssemblyFile: true);
        }
        catch
        {
        }

        try
        {
            if (Directory.Exists(sourceDirectory))
                Directory.Delete(sourceDirectory, recursive: true);
        }
        catch
        {
        }
    }
}

static void PacksWatchedFolderActivityBadgeReflectsRecentChanges()
{
    using var form = new MainForm();
    var changeField = typeof(MainForm).GetField("_lastPackRegistryChangeUtc", BindingFlags.Instance | BindingFlags.NonPublic);
    var refreshMethod = typeof(MainForm).GetMethod("RefreshPacksPanel", BindingFlags.Instance | BindingFlags.NonPublic);
    var badgeProperty = typeof(MainForm).GetProperty("PacksWatchActivityBadgeText", BindingFlags.Instance | BindingFlags.Public);
    Require(changeField != null, "MainForm should track the last watched-folder change timestamp.");
    Require(refreshMethod != null, "MainForm should refresh the Packs panel.");
    Require(badgeProperty != null, "MainForm should expose the watched-folder activity badge text.");

    changeField!.SetValue(form, DateTimeOffset.UtcNow);
    refreshMethod!.Invoke(form, new object?[] { false });
    var badgeText = badgeProperty!.GetValue(form) as string ?? string.Empty;
    Require(badgeText.Contains("Last watch:", StringComparison.OrdinalIgnoreCase), $"Expected the watched-folder activity badge to show a last-watch timestamp, got '{badgeText}'.");
    Require(!badgeText.Contains("never yet", StringComparison.OrdinalIgnoreCase), $"Expected the watched-folder activity badge to reflect a recent change, got '{badgeText}'.");
}

static void PacksRollbackBackupStatusIsVisible()
{
    var sourceAssembly = typeof(SampleCommandPack).Assembly.Location;
    var sourceDirectory = Path.Combine(Path.GetTempPath(), "Callsign.AlphaSmoke", "packs-backup-status", Guid.NewGuid().ToString("N"));
    Directory.CreateDirectory(sourceDirectory);

    try
    {
        var sourceCopy = Path.Combine(sourceDirectory, Path.GetFileName(sourceAssembly));
        File.Copy(sourceAssembly, sourceCopy, overwrite: true);

        using var form = new MainForm();
        var importMethod = typeof(MainForm).GetMethod("ImportCommunityPacks", BindingFlags.Instance | BindingFlags.NonPublic);
        Require(importMethod != null, "MainForm should expose the community pack import handler.");
        importMethod!.Invoke(form, new object[] { new[] { sourceCopy }, false });

        var backupStatusProperty = typeof(MainForm).GetProperty("PacksRollbackBackupText", BindingFlags.Instance | BindingFlags.Public);
        Require(backupStatusProperty != null, "MainForm should expose the rollback backup status text.");
        var backupStatusText = backupStatusProperty!.GetValue(form) as string ?? string.Empty;
        Require(backupStatusText.Contains("Backup:", StringComparison.OrdinalIgnoreCase), $"Expected a visible rollback backup status, got '{backupStatusText}'.");
        Require(backupStatusText.Contains("available", StringComparison.OrdinalIgnoreCase) || backupStatusText.Contains("none", StringComparison.OrdinalIgnoreCase), $"Expected the rollback backup status to explain availability, got '{backupStatusText}'.");
    }
    finally
    {
        try
        {
            CallsignCommandRegistry.Shared.RemovePack("sample-pack", out _, deleteAssemblyFile: true);
        }
        catch
        {
        }

        try
        {
            if (Directory.Exists(sourceDirectory))
                Directory.Delete(sourceDirectory, recursive: true);
        }
        catch
        {
        }
    }
}

