static void WakeCalibrationHelperScoresEnrolledSamples()
{
    var repoRoot = FindRepositoryRoot();
    var servicePath = Path.Combine(repoRoot, "src", "Callsign.UI", "Services", "VoiceCommandService.cs");
    var formPath = Path.Combine(repoRoot, "src", "Callsign.UI", "VoiceIdentityTrainingForm.cs");
    Require(File.Exists(servicePath), $"Could not find voice service source at {servicePath}.");
    Require(File.Exists(formPath), $"Could not find UI form source at {formPath}.");

    var serviceSource = File.ReadAllText(servicePath);
    Require(serviceSource.Contains("TryScoreWakeWordSampleAsync", StringComparison.OrdinalIgnoreCase), "Wake service should expose a sample scoring helper.");
    Require(serviceSource.Contains("ComputeCalibratedWakeThreshold", StringComparison.OrdinalIgnoreCase), "Wake service should expose a calibrated-threshold helper.");
    Require(serviceSource.Contains("ComputeTrustedWakeCalibrationScore", StringComparison.OrdinalIgnoreCase), "Wake service should expose a trusted sample-set helper.");
    Require(serviceSource.Contains("ApplyWakeCalibration", StringComparison.OrdinalIgnoreCase), "Wake service should expose a calibration helper that persists metadata.");
    Require(serviceSource.Contains("score < 0.05", StringComparison.OrdinalIgnoreCase), "Wake calibration should ignore uselessly tiny scores.");
    Require(serviceSource.Contains("VoiceWakeCalibrationVersion", StringComparison.OrdinalIgnoreCase), "Wake calibration should persist provenance.");

    var trustedScore = VoiceCommandService.ComputeTrustedWakeCalibrationScore(new[] { 0.10, 0.20, 0.90, 0.30 });
    Require(trustedScore.HasValue, "Wake service should produce a trusted score for a valid sample set.");
    var trustedScoreValue = trustedScore ?? throw new InvalidOperationException("Wake service should produce a trusted score for a valid sample set.");
    Require(Math.Abs(trustedScoreValue - 0.10) < 0.0001, $"Wake service should bias wake calibration toward the lower quartile of trusted samples, got {trustedScoreValue:0.000}.");
    var calibratedThreshold = VoiceCommandService.ComputeCalibratedWakeThreshold(new[] { 0.10, 0.20, 0.90, 0.30 });
    Require(calibratedThreshold.HasValue, "Wake service should calibrate from a trusted sample set.");
    var calibratedThresholdValue = calibratedThreshold ?? throw new InvalidOperationException("Wake service should calibrate from a trusted sample set.");
    Require(calibratedThresholdValue <= 0.05, $"Wake calibration from the trusted sample set should stay recall-biased, got {calibratedThresholdValue:0.000}.");

    var formSource = File.ReadAllText(formPath);
    Require(formSource.Contains("TryScoreWakeWordSampleAsync", StringComparison.OrdinalIgnoreCase), "Activation should score enrolled wake samples.");
    Require(formSource.Contains("ComputeTrustedWakeCalibrationScore", StringComparison.OrdinalIgnoreCase), "Activation should derive wake calibration from the trusted sample set.");
    Require(formSource.Contains("ApplyWakeCalibration", StringComparison.OrdinalIgnoreCase), "Activation should persist the wake threshold from enrolled samples.");
    Require(formSource.Contains("GetRecordedWakeSamplePaths", StringComparison.OrdinalIgnoreCase), "Activation should prefer dedicated wake samples.");
    Require(formSource.Contains("wake-samples", StringComparison.OrdinalIgnoreCase), "Wake calibration should look for dedicated wake samples on disk.");
    var mainFormSource = File.ReadAllText(Path.Combine(repoRoot, "src", "Callsign.UI", "MainForm.cs"));
    Require(mainFormSource.Contains("Provenance: trusted sample set.", StringComparison.OrdinalIgnoreCase), "Wake overlay should spell out trusted wake calibration provenance.");
    Require(formSource.Contains("Wake provenance", StringComparison.OrdinalIgnoreCase), "Voice training form should show wake calibration provenance.");
}

